INSERT INTO "category" VALUES(10,'我的场景',999,1);
INSERT INTO "drill" VALUES(1,1,'跨部门要资源，对方说排期满了','你是市场部的项目负责人，下周要上线一个促销活动，需要技术部的张工帮忙开发一个活动页面。你去找张工时，他皱着眉说：“这个月排期已经满了，你们市场部每次都临时加需求。”请你说明需求的价值与紧迫性，理解对方的难处，并提出可行的协作方案（如缩小范围、调整优先级、请对方领导协调），争取对方支持。','','中压',3,'纯语音','技术部开发工程师张工，工作很忙，对市场部临时加需求有怨气，但讲道理','市场部项目负责人','换位思考、需求价值表达、提出双赢的协作方案','又是你们市场部啊？这个月排期早就满了，你们每次都临时加需求，我真排不过来。','','online',0,NULL,'','["一上来就说“老板定的必须做”", "跟对方争论谁更忙", "不给缩小范围的选项"]');
INSERT INTO "drill" VALUES(2,1,'协作方一再拖延，你去催进度','你负责的新功能下周五上线，依赖数据组的接口，对方承诺的交付已经晚了一周。你去找数据组负责人周姐，她说：“我们手上还有三个更急的需求。”请你说明延期的影响，了解对方真实的卡点，在不伤关系的前提下约定一个明确的交付时间，必要时提出你能提供的支持。','','中压',3,'纯语音','数据组负责人周姐，忙且有点护短，不愿轻易给出承诺','项目负责人','讲清影响、找到卡点、锁定时间和责任人','又来催接口啊？我们手上还有三个更急的需求，真不是故意拖你们的。','','online',1,NULL,'','["只说“尽快”没有具体时间", "一上来就抄送领导施压", "不问对方真实卡点"]');
INSERT INTO "drill" VALUES(3,2,'年度绩效面谈，争取加薪','你在公司工作满两年，今年独立负责了两个重点项目，业绩超额完成 30%。年度绩效面谈时，你的直属领导刘经理说：“今年整体预算紧张，调薪幅度都不大。”请你用事实和数据说明自己的贡献，合理表达加薪诉求，同时给领导留有余地，必要时提出替代方案（如职级晋升、培训机会、下半年复议）。','','中压',4,'纯语音','直属领导刘经理，认可下属但受预算约束，会委婉推脱','工作两年、业绩突出的员工','用数据说话、坚定而不强硬、灵活提出替代方案','来，坐。今年你表现确实不错，不过我得先跟你说一下，今年整体预算比较紧张，调薪幅度普遍都不大。你自己怎么看？','','online',0,NULL,'','["只说辛苦不说成果", "拿离职威胁", "被一句“预算紧”就放弃"]');
INSERT INTO "drill" VALUES(4,2,'领导临时塞来额外工作，你想婉拒','周五下午五点，你手上的季度报告周一就要交，领导王经理突然走过来说：“隔壁组的竞品分析也交给你吧，下周一一起给我。”你确实做不完。请你在不显得推脱的前提下说明现有工作量，请领导排优先级，或提出替代方案（延期、分工、缩小范围）。','','高压',3,'纯语音','直属领导王经理，习惯把活交给靠谱的人，被拒绝时会施压','工作已经排满的员工','说“不”但不得罪人：摆事实、请对方排序、给替代方案','小张，隔壁组那个竞品分析也交给你吧，下周一跟季度报告一起给我，没问题吧？','','online',1,NULL,'','["直接说“做不完”", "全盘接下最后都交不好", "当场谈条件涨薪"]');
INSERT INTO "drill" VALUES(5,2,'老板说今年没有调薪预算','年终沟通时，老板陈总先开口：“今年公司整体效益一般，没有调薪预算，晋升名额也冻结了。”但你今年独立带了两个项目，业绩超额 25%，市场上同岗位薪资比你高 20%。请你在理解公司处境的前提下，表达你的预期，展示价值，争取一个具体的承诺（如明年上半年复议、调整岗位职级或其他补偿）。','','中压',4,'纯语音','老板陈总，确实有预算压力，会用“大家都一样”“明年再说”推脱','业绩突出的员工','先充分理解，再展示价值、给出预期，争取具体承诺','今年的情况你也知道，公司整体效益一般，调薪和晋升都冻结了，大家都一样。','','online',2,NULL,'','["一听没预算就放弃", "拿离职威胁", "只谈钱不谈价值", "没有争取到任何具体承诺就结束"]');
INSERT INTO "drill" VALUES(6,2,'向老板申请团队激励预算','你的团队连续加班两个月赶完了旺季，大家士气低落，已经有一个人提了离职。你想向老板王总申请 3 万元团队激励预算，但你知道公司现在现金流紧张。请你用事实和数据说明必要性，表现出你理解老板的处境，并准备高低两套方案。','','中压',3,'纯语音','老板王总，认可团队但对花钱谨慎，会问“不发钱能不能稳住”','团队负责人','申请资源：紧迫性、现状、已做努力、方案高低、带好消息','说吧，什么事？要钱的话可得想好理由，最近财务卡得很紧。','','online',3,NULL,'','["开口就要钱，没有数据", "只讲团队辛苦，不讲对公司的影响", "只准备一个方案，被拒就没退路"]');
INSERT INTO "drill" VALUES(7,3,'下属连续延期交付，一对一沟通','你是一个 6 人小组的组长。组员小王最近连续两次延期交付，影响了整个项目进度，但他平时能力不错。你约他做一次一对一沟通。请你先了解原因，再明确指出问题和影响，最后和他一起制定改进计划，既要解决问题，也要保护他的积极性。','','低压',3,'纯语音','组员小王，能力不错但最近状态下滑，一开始有点防御','6 人小组的组长','倾听询问、就事论事给反馈、共同制定改进计划','组长，你找我？……是不是因为上周那个需求又延期了的事？','','online',0,NULL,'','["一开口就定性“你最近态度有问题”", "只批评不了解原因", "没有约定后续跟进"]');
INSERT INTO "drill" VALUES(8,3,'给刚入职的新人布置第一个任务','新人小林入职第三天，你要把一个用户调研整理的任务交给她。她看起来有点紧张，不太敢提问。请你用清晰的方式说明任务背景、交付标准、截止时间和可以求助的人，并确认她真的听懂了，让她既有压力也有安全感。','','低压',3,'纯语音','新人小林，认真但紧张，听不懂也不太敢问，被鼓励后会主动提问','小林的直属组长','布置任务讲清目标、标准、时间、资源，并确认理解','组长好，您找我是有新任务吗？我……我会好好做的。','','online',1,NULL,'','["只说“你先弄一下”", "不说交付标准", "不确认对方是否听懂"]');
INSERT INTO "drill" VALUES(9,3,'绩效不达标，进行改进面谈','组员老陈连续两个季度绩效不达标，按公司规定需要进入绩效改进计划。他在公司六年，资历比你还老，情绪可能比较大。请你坦诚说明事实和数据，倾听他的想法，明确改进目标和时间节点，同时保持尊重，避免让谈话变成争吵。','','高压',4,'纯语音','老员工老陈，觉得自己被针对，会翻旧账、质疑考核公平性','新上任的组长','对事不对人、用数据说话、稳住情绪、落实改进计划','绩效改进？我在这干了六年，你来了才半年，就要给我上 PIP？','','online',2,NULL,'','["被“资历老”压住不敢说事实", "人身攻击或翻旧账", "目标模糊没有时间节点"]');
INSERT INTO "drill" VALUES(10,3,'下属失误造成损失，私下批评','下属小周在给客户发货时没有核对地址，导致一批货发错，公司多花了 8000 元运费，还被客户投诉。这已经是他这个季度第二次类似失误。请你私下和他谈一次：讲清问题和影响，了解原因，一起制定改进办法，并约定检查时间，对事不对人。','','中压',3,'纯语音','下属小周，知道自己错了但有点委屈，会解释“当时太忙了”','小周的直属主管','批评六步：主题、全貌、影响、建议、征询、约定','主管，您找我……是因为发错货的事吧？','','online',3,NULL,'','["当着全组的面批评", "翻旧账、上升到人品", "只骂不给方法", "批评完没有跟进"]');
INSERT INTO "drill" VALUES(11,3,'说服骨干接受调岗','公司要开拓线上业务，你想调团队里最得力的骨干小林去牵头，但他在线下做得很好，担心转岗后做不好、影响收入。请你和他一对一沟通：讲清背景，理解他的顾虑，说明为什么选他、对他职业发展的价值，并给他考虑的时间。','','中压',4,'纯语音','骨干小林，能力强但求稳，担心收入和失败，会提出一连串顾虑','部门经理','说服下属：背景、共情、选你的理由、长期价值、听意见、坐实','经理，听说要调我去做线上？我在线下刚做顺手，说实话有点担心。','','online',4,NULL,'','["用职位压人“这是公司决定”", "被顾虑带跑，最后放弃", "只画饼没有具体支持"]');
INSERT INTO "drill" VALUES(12,3,'下属情绪低落，帮他重回状态','下属小雨最近负责的方案连续被客户否定了三次，这两天上班明显没精神，开会也不说话。请你找她聊一聊，先接住她的情绪，了解她的想法，再帮她找到下一步，让她重新有信心。','','低压',3,'纯语音','下属小雨，很沮丧，开始会说“我是不是不适合做这个”','小雨的组长','先处理情绪再处理事情：接纳、鼓励分享、理解、共同策划','组长……我是不是真的不适合做方案？改了三次客户都说不行。','','online',5,NULL,'','["一上来讲道理“这点挫折算什么”", "急着给解决方案", "只安慰不帮她找下一步"]');
INSERT INTO "drill" VALUES(13,4,'会议跑题争吵，你来拉回主线','你主持一场产品需求评审会，议题是确定下个版本的三个核心功能。会议进行到一半，运营的小陈和设计的老周因为一个按钮颜色争执起来，已经偏题十分钟。请你礼貌地打断，肯定双方的观点，把讨论拉回主议题，并给出明确的后续处理方式和时间安排。','','中压',3,'纯语音','运营小陈，情绪有点激动，坚持自己的观点，会试图继续争论','产品需求评审会的主持人','适时打断、中立肯定、拉回议程、明确行动项','不是，老周你听我说完！这个按钮必须用红色，用户根本注意不到灰色的，数据我都看过……','','online',0,NULL,'','["站队支持一方", "粗暴打断“别吵了”", "不给分歧的后续处理方式"]');
INSERT INTO "drill" VALUES(14,4,'汇报时被领导连续质疑数据','你在月度经营会上汇报渠道投放效果，刚讲到转化率提升 20%，财务总监李总就打断你：“这个口径我不认，你的分母是怎么算的？”其他人都看着你。请你保持镇定，先回应质疑、说明口径，承认不足的地方，并把会议拉回你要大家做的决策上。','','高压',3,'纯语音','财务总监李总，严谨挑剔，会连续追问数据口径和可信度','市场部汇报人','被质疑时不慌：先接住、再解释、再拉回决策','等一下，这个 20% 我不认。你的分母是怎么算的？去年同期的口径一样吗？','','online',1,NULL,'','["慌张、语无伦次", "跟领导争辩", "答完质疑忘了拉回决策"]');
INSERT INTO "drill" VALUES(15,4,'主持部门周会，开个好头','你第一次主持部门周会，一共 8 个人、1 小时，要过一遍上周进度，并讨论两个议题：下月的活动预算和新人培训安排。大家进会议室时还在聊天看手机。请你做一个开场：破冰、点明主题、说明安排和目标、立下会议规则，然后进入第一个议题。','','低压',2,'纯语音','部门同事老张，爱聊天，开会时偶尔看手机，会插一两句话','第一次主持周会的你','会议开场：破冰-主题-安排-目标-规则','（还在聊天）哎，昨天那场球你看了没……哦，要开始了？','','online',2,NULL,'','["没有议程，想到哪说到哪", "开场太长，自己讲了 10 分钟", "不提规则，会议一直被打断"]');
INSERT INTO "drill" VALUES(16,4,'早会上汇报今天的工作','部门早会每个人有 1 分钟汇报当天工作。你今天手上有三件事：给客户 A 改方案、跟财务对账、面试一个候选人，其中对账需要同事小王配合。请你用结构化的方式汇报，并说清需要谁配合什么。','','低压',2,'纯语音','部门主管，会对不清楚的地方追问一句','部门员工','早会汇报：结论先行，逐项讲进度、困难和需要的支持','好，下一个，你说说今天的安排。','','online',3,NULL,'','["流水账讲细节，超时", "不说需要谁配合", "只说做什么，不说进度和风险"]');
INSERT INTO "drill" VALUES(17,5,'电梯偶遇大老板，30 秒闲聊','早上你在电梯里偶遇公司的赵总，电梯里只有你们两个人，大约有 30 秒到一分钟的时间。赵总主动问你：“最近在忙什么呀？”请你自然得体地回应，简要介绍自己的工作亮点，并找到一个轻松的话题延续交流，给老板留下积极的印象。','','低压',2,'纯语音','公司赵总，亲和但时间宝贵，会随口追问一两句','普通员工','简洁表达工作亮点、自然寒暄、把握分寸','早啊！你是……产品部的吧？最近在忙什么呀？','','online',0,NULL,'','["紧张只回“还好”", "趁机长篇汇报", "抱怨工作"]');
INSERT INTO "drill" VALUES(18,5,'和新同事第一次一起吃午饭','部门新来了一位同事小吴，今天中午你们俩恰好一起去食堂。他话不多，一路有点安静。请你自然地开启话题，了解他的背景和兴趣，介绍一些部门里的情况，让他感到被欢迎，又不让人觉得在打听隐私。','','低压',2,'纯语音','新同事小吴，内向但友善，问到感兴趣的话题会多说几句','部门老员工','开放式提问、适度自我暴露、把握隐私边界','嗯……食堂人好多啊。你平时都来这吃吗？','','online',1,NULL,'','["查户口式提问", "一直讲自己", "打听薪资等隐私"]');
INSERT INTO "drill" VALUES(19,6,'项目出现风险，主动向领导汇报','你负责的客户交付项目发现一个风险：核心供应商可能延期两周，会影响合同里约定的上线时间。你决定主动去找部门总监赵总汇报。请你用“结论—原因—影响—方案—需要的支持”的结构，在 2 分钟内把情况说清楚，并争取到领导的决策或资源。','','中压',3,'纯语音','部门总监赵总，时间紧，不喜欢绕弯子，会追问“你的建议是什么”','项目经理','结论先行、带着方案汇报、明确需要领导做什么','你说吧，我十分钟后还有个会。什么事？','','online',0,NULL,'','["只报问题不带方案", "铺垫背景太长", "等风险变成事故才汇报"]');
INSERT INTO "drill" VALUES(20,6,'年中述职，向领导争取下半年资源','年中述职时，你需要向分管副总裁孙总汇报上半年业绩，并申请下半年增加两个人的编制。上半年你的团队完成了 115% 的目标，但公司整体在控制人力成本。请你用数据讲清成果，说明加人的必要性和投入产出，并准备好应对质疑。','','中压',4,'纯语音','分管副总裁孙总，认可成绩但对加编制很谨慎，会问“不加人能不能做”','业务团队负责人','用数据证明价值、算清投入产出、提出可退让的方案','上半年的成绩我看到了，不错。不过你邮件里提的加两个编制，我想先听听你的理由。','','online',1,NULL,'','["只讲成绩不算投入产出", "只准备一个方案", "被问“不加人能不能做”时答不上来"]');
INSERT INTO "drill" VALUES(21,6,'老板交代的任务没说清楚，你来确认','周一早上，老板张总路过你工位，随口说：“下周要见渠道商，你准备一份材料。”说完就要走。你完全不清楚要准备什么样的材料。请你用几个关键问题快速和老板确认任务的目标、范围、交付形式和时间，既不把老板问烦，又避免做完返工。','','低压',2,'纯语音','老板张总，忙、说话简略，被问太多细节会不耐烦，但关键问题会回答','部门骨干','用骨架问题确认任务：目标、范围、交付、时间、资源','小李，下周要见渠道商，你准备一份材料，我先去开会了。','','online',2,NULL,'','["只回一句“好的”就闷头做", "一口气问十几个细节，把老板问烦", "不确认交付时间，最后被催"]');
INSERT INTO "drill" VALUES(22,6,'线上故障，第一时间向老板汇报','晚上九点，你负责的支付系统出了故障，过去一小时有约 300 笔订单没有支付成功，客服电话被打爆。你已经让技术排查，初步判断是第三方接口问题。现在你要给老板打电话汇报。请你在 1 分钟内讲清楚发生了什么、影响多大、你准备怎么处理，以及需要老板决策什么。','','高压',3,'纯语音','老板刘总，被晚上打扰有点急，会追问影响和责任','支付系统负责人','突发事件汇报：定性、影响、方案对比、给出倾向、请示决策','喂，这么晚打电话，出什么事了？','','online',3,NULL,'','["慌张地只说“出大事了”", "等原因完全查清楚才汇报", "急着撇清责任", "只报问题不带方案"]');
INSERT INTO "drill" VALUES(23,7,'提出离职，被领导极力挽留','你已经拿到了一家更好公司的 offer，决定离职。你约了直属领导何总谈话。何总很器重你，可能会用加薪、升职或感情牌挽留你。请你坦诚而坚定地表达离职决定，感谢领导的培养，商定交接安排，同时保持良好关系。','','中压',3,'纯语音','直属领导何总，器重你，会先打感情牌，再尝试用加薪挽留','决定离职的骨干员工','坚定表达决定、真诚感谢、谈好交接，不留下坏印象','听说你想跟我聊聊？是不是最近有什么想法，跟我直说。','','online',0,NULL,'','["吐槽公司和领导", "被加薪打动当场改口又后悔", "透露下家具体信息"]');
INSERT INTO "drill" VALUES(24,8,'被老板当面批评工作失误','你在给客户的报价单里算错了一个数，少报了 2 万元，客户已经确认了。老板周总把你叫进办公室，非常生气：“这么低级的错误也会犯？你知道公司要损失多少吗？”请你先接住老板的情绪，真诚认错，不找借口，再给出补救方案，并借机了解老板对你的其他期待。','','高压',3,'纯语音','老板周总，非常生气，前期会连续批评，听到真诚认错和补救方案后会缓和','犯错的业务员','接住情绪、真诚认错、给补救方案、请教改进','这么低级的错误也会犯？报价单你自己都不检查一遍吗？你知道公司要亏多少吗？','','online',0,NULL,'','["急着解释“系统模板有问题”", "说“下次注意”就完了", "被批评后情绪低落、躲着老板"]');
INSERT INTO "drill" VALUES(25,9,'项目关键期，向老板请两天假','下周三四，你需要回老家处理家里的事情，但那周正是项目交付的关键期。你需要私下向老板刘姐请两天假。请你说明情况（不必讲太多细节），表现出你清楚工作的重要性，并给出完整的工作安排，让老板放心批假。','','中压',2,'纯语音','老板刘姐，担心项目进度，会追问“工作怎么办”','项目组成员','请假：私下请、讲清工作安排、给出交付承诺','嗯？找我什么事？最近项目这么紧。','','online',0,NULL,'','["理由讲太多细节", "在群里或会上请假", "只说请假，不说工作怎么办", "姿态太卑微，反而让人不放心"]');
INSERT INTO "drill" VALUES(26,10,'同事想把他的活推给你','下午四点，同事老马走过来：“帮个小忙，这份月报你顺手做一下呗，就是把数据填进去，很快的。”你知道这份月报至少要两个小时，而你手上的方案今天要交。这已经是他这个月第三次让你“帮小忙”。请你得体地拒绝或部分接受，守住边界又不伤同事关系。','','中压',2,'纯语音','同事老马，爱占小便宜但人不坏，被拒绝会说“就一会儿的事”','部门同事','说“不”的艺术：接住、讲清现状、给替代方案、守住边界','帮个小忙呗，这份月报你顺手做一下，就是把数据填进去，很快的。','','online',0,NULL,'','["碍于面子全部接下，自己加班", "直接甩脸色", "每次都上升到找领导评理"]');
INSERT INTO "drill" VALUES(27,10,'同事把出错的锅甩给你','周会上，客户投诉的数据错误被提了出来。同事小郑先开口：“数据是小李那边提供的，我只是做了汇总。”但实际上原始数据没问题，是汇总时公式写错了。领导看向你。请你冷静地澄清事实，不互相指责，把讨论拉回到怎么解决问题上，展现你的格局。','','高压',3,'纯语音','领导，想尽快弄清楚责任并解决问题，会追问细节','被甩锅的员工','冷静澄清：讲事实不指责，把话题拉回解决问题','小李，小郑说数据是你提供的，你怎么说？','','online',1,NULL,'','["当场情绪激动反甩回去", "不敢说话默默背锅", "只顾自证清白，不提解决办法"]');
INSERT INTO "drill" VALUES(28,10,'被同事抢了功劳','你花了两周做的竞品分析，在部门会上被同事小吴当成自己的成果讲了，领导还表扬了他。会后你决定找小吴聊一聊，同时也想让领导知道你的贡献。请你先和小吴沟通，表达你的感受和诉求，不撕破脸。','','中压',3,'纯语音','同事小吴，有点心虚，会说“我们是一个团队嘛”','被抢功的员工','用事实和感受表达诉求，不指责，守住自己的成果','哦，是你啊，有什么事吗？','','online',2,NULL,'','["当面质问“你为什么抢我功劳”", "忍着不说，背后抱怨", "直接越级去告状"]');
INSERT INTO "drill" VALUES(29,11,'向甲方提案，客户说“感觉不对”','你带着团队做了两周的品牌活动方案给客户汇报，讲完后客户市场总监赵总说：“嗯……感觉不太对，没有我想要的那种感觉。”但他说不出具体哪里不对。请你冷静地澄清问题：先确定是整体方向还是局部细节的问题，用专业的方式引导他说出真实需求，并约定下一步。','','高压',4,'纯语音','客户市场总监赵总，凭感觉判断，说不清具体要求，有点挑剔','乙方项目负责人','提案说服：重申目标、先定结构再谈细节、给方案选择','嗯……讲得挺多的，但感觉不太对，没有我想要的那种感觉。','','online',0,NULL,'','["急着辩解方案多好", "客户一说不行就全部推翻重做", "不追问，回去瞎猜"]');
INSERT INTO "drill" VALUES(30,11,'客户要加需求，却不加预算','项目进行到一半，客户王经理说：“我们老板说再加两个页面，应该不难吧，就不另外算钱了啊。”加这两个页面需要额外一周的工作量。请你既维护客户关系，又守住项目的范围和利润，提出可行的方案（如调整排期、置换其他需求、走需求变更）。','','中压',3,'纯语音','客户王经理，压力来自他老板，希望你别为难他','乙方项目经理','有条件让步：理解对方、讲清影响、交换条件','我们老板说再加两个页面，应该不难吧？这个就不另外算钱了啊，都合作这么久了。','','online',1,NULL,'','["碍于关系直接答应", "一口回绝说“合同里没有”", "答应了但不说影响，最后延期"]');
INSERT INTO "drill" VALUES(31,11,'电话向陌生客户介绍产品','你是一家企业培训公司的销售，今天要给一位从没接触过的人力资源总监孙总打电话，介绍你们的“中层管理沟通课”。对方很忙，一般只给你两分钟。请你快速建立信任，先了解对方需求，再介绍和对方相关的价值，争取一个见面机会。','','中压',3,'纯语音','人力资源总监孙总，很忙、对推销电话有戒心，听到相关痛点会感兴趣','培训公司销售','销售：建立信任、先问需求、讲相关价值、约下一步','喂，哪位？我在开会，长话短说。','','online',2,NULL,'','["一接通就念产品介绍", "对方说忙还继续讲", "不约下一步，挂了电话就没下文"]');
INSERT INTO "drill" VALUES(32,12,'年终客户答谢宴，你来致祝酒词','公司年终客户答谢宴，十几位重要客户和公司领导都在场。领导临时让你作为项目负责人，给大家敬第一杯酒并说几句。请你用 1 分钟左右的祝酒词，感谢客户一年来的支持，回顾合作成果，表达对来年的期待，营造热络得体的氛围。','','中压',3,'纯语音','公司领导王总，在桌上点名让你说话，之后会以客户身份接话回应','项目负责人','结构清晰的祝酒词：感谢—回顾—祝福，语气真诚热情','来来来，大家静一静！今天咱们项目负责人也在，这一年辛苦了，你代表咱们团队先给各位贵宾敬一杯，说两句！','','online',0,NULL,'','["讲太长菜都凉了", "只感谢领导忘了客户", "举杯前没停顿"]');
INSERT INTO "drill" VALUES(33,12,'好友婚宴上，作为伴郎/伴娘致辞','你最好的朋友今天结婚，司仪临时请你作为伴郎（伴娘）上台说几句。台下有两百位宾客，包括新人的父母长辈。请你用 1-2 分钟讲一个你们之间的真实小故事，表达对新人的祝福，做到既有趣又得体，不让场面尴尬。','','中压',3,'纯语音','婚礼司仪，先请你上台，之后会以宾客和新郎的身份接话互动','新人的好友（伴郎/伴娘）','讲好一个小故事、幽默有分寸、真诚送上祝福','接下来，有请新郎最好的兄弟，也是今天的伴郎，上台为新人送上祝福！大家掌声欢迎！','','online',1,NULL,'','["爆新郎的黑料或前任", "只讲你和新郎，忘了新娘", "超时"]');
INSERT INTO "drill" VALUES(34,13,'饭局冷场，你来破冰','你参加一个朋友组织的饭局，桌上有一半人互相不认识，开席十分钟大家都在低头看手机，气氛有点冷。坐在你旁边的是第一次见面的李先生。请你找合适的话题开启聊天，并逐步把更多人带进话题，让气氛热起来。','','低压',3,'纯语音','饭局上第一次见面的李先生，有点拘谨，起初回答简短，被带动后会逐渐放开','饭局参与者','寻找共同话题、开放式提问、把话题抛给更多人','（放下手机）嗯？你好你好……你也是小周的朋友？','','online',0,NULL,'','["只和熟人聊", "问题一句就聊死", "开不合适的玩笑"]');
INSERT INTO "drill" VALUES(35,13,'部门团建聚餐，大领导也在场','部门团建晚饭，分管副总也来了，大家都有点拘谨，只有零星的碰杯声。你的直属领导朝你使眼色，希望你带动一下气氛。请你找一个大家都能参与的话题或小游戏，自然地把副总也带进来，让气氛轻松起来又不失分寸。','','中压',3,'纯语音','分管副总冯总，平时严肃，起初回应很简短，被真诚带动后会放开','部门里比较活跃的员工','找全员可参与的话题、照顾领导、不失分寸','（放下筷子）大家别拘束啊，该吃吃该喝喝。……你们平时团建都玩些什么？','','online',1,NULL,'','["把领导晾在一边", "拍马屁太露骨", "玩游戏让领导下不来台"]');
INSERT INTO "drill" VALUES(36,14,'同事说错话，客户脸色一沉','你和同事小张陪客户吃饭。小张喝多了，随口说了一句：“你们公司上次那个付款拖了三个月，我们财务都快疯了。”客户孙总脸色一沉，桌上瞬间安静。请你迅速圆场，化解尴尬，既维护客户面子，又不让同事下不来台，把气氛重新带回来。','','高压',3,'纯语音','客户孙总，被冒犯后有些不悦，语气冷淡，会试探你们公司的态度','陪同客户吃饭的业务负责人','快速反应、幽默或真诚化解尴尬、照顾各方面子','（放下筷子）哦？拖了三个月？那看来我们合作得挺让你们为难的啊。','','online',0,NULL,'','["当场批评同事", "假装没听见", "越解释越尴尬"]');
INSERT INTO "drill" VALUES(37,15,'饭桌上请老前辈引荐资源','你在创业，正在找一家大型连锁超市的采购渠道。今晚的饭局上，你终于和行业老前辈陈总坐在了一起，他和这家超市的采购总监关系很好。请你在合适的时机自然地提出请求，说清楚你的项目价值，让陈总愿意帮你引荐，同时不让对方感到被利用。','','中压',4,'纯语音','行业老前辈陈总，阅历丰富、爱惜羽毛，不会轻易答应帮忙，会考察你','创业者','铺垫关系、把握时机、清晰表达价值、给对方台阶','小伙子，听说你最近在创业？做的什么项目啊，说来听听。','','online',0,NULL,'','["一坐下就开口求人", "说不清项目价值", "被婉拒后脸色难看"]');
INSERT INTO "drill" VALUES(38,15,'饭局上委婉催客户回款','客户公司拖欠了你们三个月的货款共 80 万，你的老板让你借今晚的饭局跟客户财务负责人钱总提一提。你既要把回款的事说清楚、拿到一个时间，又不能让对方觉得被逼债、伤了合作关系。','','高压',3,'纯语音','客户财务负责人钱总，打太极高手，会以“流程”“资金紧”为由拖延','供应商的销售负责人','找准时机开口、把事说清、拿到具体回款时间','哎呀，今天这菜不错。最近你们生意怎么样？我们这边是真不好做啊。','','online',1,NULL,'','["当着一桌人说钱", "只说“尽快”", "开口太晚，饭局散了还没提"]');
INSERT INTO "drill" VALUES(39,16,'重要饭局迟到 40 分钟','今晚是部门为新领导接风的饭局，你因为临时处理客户问题迟到了 40 分钟。你推门进去时，大家已经吃了一半，有同事起哄：“迟到的要先自罚三杯！”新领导吴总也看着你。请你得体地道歉、说明原因（不找借口）、应对罚酒，并顺势向新领导表示欢迎。','','中压',2,'纯语音','起哄的同事老刘，爱热闹，会坚持让你罚酒；新领导吴总偶尔插话','迟到的部门员工','真诚道歉、得体应对劝酒、顺势表达欢迎','哎哟，大忙人终于来了！迟到四十分钟啊，按规矩先自罚三杯！吴总可都等你半天了。','','online',0,NULL,'','["解释一大堆", "拒绝罚酒扫兴", "忘了新领导"]');
INSERT INTO "drill" VALUES(40,17,'客户热情劝酒，你要开车','你开车来参加客户的饭局，客户吴总端着酒杯走过来：“今天这杯你必须喝，不喝就是不给我面子！”你明确不能喝酒。请你在不扫兴、不得罪客户的前提下坚定拒绝，用其他方式表达敬意，把气氛维持住。','','高压',2,'纯语音','客户吴总，热情豪爽，劝酒很坚持，会说“就一小口”','开车赴宴的业务代表','坚定拒酒、给足面子、用替代方式表达敬意','来来来，今天这杯你必须喝！不喝就是不给我吴某人面子啊！','','online',0,NULL,'','["被劝两句就喝了", "生硬拒绝“我不喝”", "拒酒后不再敬"]');
INSERT INTO "drill" VALUES(41,17,'长辈在家宴上让你多喝几杯','春节家宴，舅舅几杯酒下肚，一直让你“陪他喝几杯”，你明天一早要赶飞机，不想喝多。亲戚们也在起哄。请你用尊重长辈的方式婉拒，表达对舅舅的心意，又不让场面难看。','','中压',2,'纯语音','热情的舅舅，喝得有点多，会打感情牌：“舅舅平时对你不好吗？”','回家过年的晚辈','尊重长辈、说明原因、用敬茶或陪聊代替喝酒','来，外甥，陪舅舅喝几杯！一年就见这一回，你可不能推啊！','','online',1,NULL,'','["当众顶撞长辈", "被感情牌说服喝多", "只拒绝不表达心意"]');
INSERT INTO "drill" VALUES(42,18,'面试自我介绍有方法，助你迅速赢得考官青睐','你正在参加一家互联网公司的产品经理岗位面试，面试官是部门负责人郑总。面试开始，郑总说：“先用两分钟做个自我介绍吧。”请你结合目标岗位，用“我是谁—我做过什么—我为什么适合”的结构，突出与岗位相关的经历和成果，并准备好应对面试官的追问。','','低压',4,'纯语音','面试官郑总，专业友善，会针对你提到的经历追问一两个细节','应聘产品经理的求职者','结构化自我介绍、突出岗位匹配度、用成果说话','你好，欢迎来面试。我们开始吧，先用两分钟做个自我介绍。','','online',0,NULL,'','["念简历", "讲与岗位无关的经历", "超过 2 分钟"]');
INSERT INTO "drill" VALUES(43,18,'应届生校招面试，一分钟自我介绍','你是一名应届毕业生，正在参加一家快消公司管培生项目的群面后单面。面试官说：“用一分钟介绍一下你自己，重点说说为什么适合这个岗位。”请你结合校园经历、实习和社团，突出学习能力和主动性，避免流水账。','','低压',3,'纯语音','HR 面试官，友善但会针对你提到的经历追问细节','应届毕业生','一分钟讲清亮点、用 STAR 方法讲经历、匹配岗位要求','同学你好，放轻松。我们时间有限，先用一分钟介绍一下你自己吧。','','online',1,NULL,'','["从小学讲起", "只列奖项没有细节", "背稿痕迹太重"]');
INSERT INTO "drill" VALUES(44,19,'面试官连续质疑你的经历','你在面试一家头部互联网公司的运营岗位。终面面试官看着你的简历，语气很冲：“你这个项目增长 300%，基数那么小，有什么意义？”接着还会连续追问。请你保持冷静，不卑不亢地回应质疑，用事实和思考过程证明你的能力。','','高压',4,'纯语音','终面面试官，故意施压、打断、质疑，观察候选人的抗压能力','求职者','情绪稳定、正面回应质疑、展示思考过程而非结果','我看了你的简历。这个项目增长 300%，但基数那么小，说实话我觉得没什么意义。你怎么看？','','online',0,NULL,'','["被激怒或语气变冲", "立刻否定自己的项目", "答非所问"]');
INSERT INTO "drill" VALUES(45,20,'HR 问你的期望薪资','你通过了某公司的所有面试，HR 打电话来沟通 offer：“你目前薪资是多少？期望多少？”你目前月薪 15k，市场同岗位在 18-22k，你希望拿到 20k。请你合理表达期望，用自身价值和市场行情支撑，面对压价时灵活谈判（如签字费、期权、调薪周期）。','','中压',3,'纯语音','HR 招聘经理，会尝试压价，说“预算有限”“内部要平衡”','拿到 offer 意向的候选人','不先亮底牌、用价值和行情说话、谈整体回报','恭喜你通过了面试！我们来聊聊 offer 吧。你现在的薪资是多少？期望多少？','','online',0,NULL,'','["先报出现在的底薪当锚点", "说“看着给”", "一次让到底"]');
INSERT INTO "drill" VALUES(46,21,'“你为什么离开上一家公司？”','你在上一家公司只待了一年就离职了，真实原因是和领导理念不合、成长空间有限。面试官问：“你为什么离开上一家公司？”随后可能追问“你最大的缺点是什么”。请你诚实但积极地回答，不抱怨前东家，把话题引向你对新岗位的期待。','','中压',3,'纯语音','业务部门面试官，经验丰富，会顺着你的回答深挖','求职者','诚实不抱怨、正向表达、把问题转为展示动机','我注意到你在上一家公司只待了一年，能说说为什么离开吗？','','online',0,NULL,'','["吐槽前公司或领导", "讲长故事", "理由前后矛盾"]');
INSERT INTO "drill" VALUES(47,21,'“说说你最大的缺点”','面试进入后半段，面试官看着你说：“说说你最大的缺点吧，要真实一点的。”请你真诚地说出一个真实但不致命的缺点，讲清楚你是怎么发现的、为什么会这样、你做了什么改进、现在的状态如何。','','中压',2,'纯语音','面试官，经验丰富，对“我太追求完美”这类回答会追问','求职者','劣势回答：识别-原因-改进-现状','说说你最大的缺点吧，要真实一点的，别说你太追求完美。','','online',1,NULL,'','["说一个其实是优点的缺点", "说一个致命的缺点“我经常迟到”", "只说缺点不说改进"]');
INSERT INTO "drill" VALUES(48,21,'简历上有 8 个月空窗期','面试官翻着你的简历问：“你去年 3 月到 11 月，这 8 个月是在做什么？”实际上你裸辞后休息了一段时间，也做了一些自由职业的项目，学了数据分析。请你淡定、简短地说明，把空窗期填充上价值，并自然地把话题引到你的优势上。','','中压',2,'纯语音','面试官，会追问空窗期的细节和你的稳定性','求职者','敏感问题闭环：淡定、简短、填充价值、转回优势','你去年 3 月到 11 月，这 8 个月是在做什么？','','online',2,NULL,'','["讲成一个长长的故事", "心虚、支支吾吾", "说身体原因又不说清楚，让人担心"]');
INSERT INTO "drill" VALUES(49,21,'面试被问到完全没准备的问题','面试官突然问：“如果让你来负责我们的海外市场，你第一个月会做什么？”你从来没做过海外市场，也没准备过这个问题。请你不慌不忙地争取思考时间，用一个清晰的框架给出初步想法，展现你的思考能力。','','中压',2,'纯语音','面试官，想看你的思维方式而不是标准答案','求职者','不会的问题：争取时间、给框架、补细节','如果让你来负责我们的海外市场，你第一个月会做什么？','','online',3,NULL,'','["直接说“我不知道”", "沉默太久", "硬编具体数字被追问"]');
INSERT INTO "drill" VALUES(50,22,'“讲讲你最有成就感的项目”','面试官说：“讲讲你过去最有成就感的一个项目吧。”请你挑一个和应聘岗位相关的项目，用 STAR 的结构讲清楚背景、你的任务、你具体做了什么、结果如何，并用参照标准让数据有说服力。准备好应对面试官的追问。','','中压',3,'纯语音','面试官，会针对你的行动和数据追问细节，判断真实性','求职者','STAR + 业绩展示：先立标准再给数据，讲清“我”做了什么','讲讲你过去最有成就感的一个项目吧。','','online',0,NULL,'','["一直说“我们”，听不出个人贡献", "只说过程没有结果", "数字说不清来源，被追问就卡住"]');
INSERT INTO "drill" VALUES(51,23,'面试官问：“你还有什么问题想问我？”','面试接近尾声，面试官合上笔记本说：“我这边问完了，你还有什么问题想问我的吗？”请你利用这个机会：可以补充一个刚才没讲到的亮点，也可以问 1-2 个高质量的问题（如对岗位的期待、团队情况），给面试画上一个好句号。','','低压',2,'纯语音','面试官，会认真回答你的问题，对“我通过了吗”这类问题会觉得减分','求职者','反问面试官：补充亮点 + 问期待/团队/考核','好，我这边问完了。你还有什么问题想问我的吗？','','online',0,NULL,'','["“我没有问题了”", "“我通过了吗？”", "上来就问工资福利"]');
INSERT INTO "drill" VALUES(52,24,'行业沙龙上结识分享嘉宾','你参加了一场行业沙龙，刚才的分享嘉宾林老师讲得非常精彩。茶歇时你走到林老师身边，想认识他并建立联系。请你用具体、真诚的赞美开启对话（避免空洞的“讲得真好”），自然地介绍自己，并争取到加微信或后续交流的机会。','','低压',3,'纯语音','分享嘉宾林老师，客气但被很多人围着，对泛泛的夸奖反应平淡，对具体的问题感兴趣','行业沙龙参会者','具体真诚的赞美、自然自我介绍、提出连接请求','（端着咖啡转过身）你好，有什么事吗？','','online',0,NULL,'','["只说“讲得真好”", "占用嘉宾太久", "不留联系方式"]');
INSERT INTO "drill" VALUES(53,24,'在会上公开认可同事的付出','项目复盘会上，同事小何为了赶进度连续加班，修复了一个关键 bug，但她自己没提。轮到你发言时，你想当着大家的面认可她的付出。请你用具体的事实和影响来表达感谢，真诚而不肉麻，让认可真正被大家看到。','','低压',2,'纯语音','会议主持人刘经理，请你发言，之后小何会害羞地回应','项目组成员','具体描述行为和影响、当众认可、真诚不浮夸','好，下面请你说说这次项目里你的感受和收获吧。','','online',1,NULL,'','["夸得太空", "顺带夸自己", "夸一个人忽略了其他人"]');
INSERT INTO "drill" VALUES(54,25,'向不太熟的邻居借车位','你的父母下周来住一周，需要一个停车位。你注意到楼上邻居周阿姨的车位一直空着，但你们只是点头之交。今天在楼下碰到她，请你礼貌地开口请求借用车位一周，说明情况，主动提出回报方式，并在对方犹豫时得体应对。','','低压',3,'纯语音','邻居周阿姨，和善但有些谨慎，会担心车位被长期占用','小区住户','礼貌开口、说清需求与期限、主动给对方保障和回报','哎，小伙子，下班啦？','','online',0,NULL,'','["不说清借多久", "不提回报", "被犹豫时直接放弃"]');
INSERT INTO "drill" VALUES(55,25,'请同事帮你顶一天班','你下周三家里有急事需要请假，但那天正好轮到你值班。你想请平时关系一般的同事小谭帮你顶一天。请你说明情况、表达歉意，提出回报方式（如换班），并在她犹豫时给出让她容易答应的方案。','','低压',2,'纯语音','同事小谭，愿意帮忙但那天也有安排，会犹豫','需要换班的同事','说清原因、降低对方成本、给出明确回报','嗯？你找我有事吗？','','online',1,NULL,'','["说不清原因", "不提回报", "临时才开口"]');
INSERT INTO "drill" VALUES(56,25,'请不熟的前辈帮忙内推','你想跳槽到一家互联网公司的市场部，发现大学校友群里的一位前辈刘姐正在那家公司做市场总监，但你们从来没说过话。你决定给她打个电话（已经通过群加了好友并约好时间），请她帮忙内推。请你说清自己是谁、为什么找她、需要她做什么，并让她帮忙的成本尽可能低。','','中压',3,'纯语音','前辈刘姐，热心但谨慎，不想随便推荐不了解的人','想跳槽的校友','开口求助：说清需求、给出理由、降低对方成本和风险、准备备选','你好，我是刘姐。你说找我有点事？','','online',2,NULL,'','["过于客套半天不进正题", "什么材料都没准备", "被婉拒后就放弃（其实可以请教问题）"]');
INSERT INTO "drill" VALUES(57,26,'聚会上被当众调侃收入','同学聚会上，一位多年不见的老同学当着大家的面说：“听说你还在那个小公司啊？一个月能挣多少，够在这儿买个厕所吗？”大家都笑了，看向你。请你保持风度，既不卑不亢地回应冒犯，又不把气氛搞僵，必要时巧妙地把话题转移开。','','高压',2,'纯语音','爱炫耀、说话不过脑子的老同学大刘，会继续调侃一两句','参加同学聚会的你','情绪稳定、幽默或坚定地设立边界、转移话题','哈哈，听说你还在那个小公司啊？一个月能挣多少，够在咱这儿买个厕所吗？','','online',0,NULL,'','["当场翻脸", "认真报收入证明自己", "反唇相讥"]');
INSERT INTO "drill" VALUES(58,26,'同事当众开你外貌的玩笑','部门聚餐时，同事老郑当着大家的面笑着说：“哎，你最近又胖了吧？是不是天天加班点夜宵？”周围有人跟着笑。你心里不舒服。请你保持风度，用幽默或坚定的方式回应，清楚地表达边界，又不至于把关系搞僵。','','中压',2,'纯语音','说话随意的同事老郑，没有恶意但不懂分寸，会再补一句玩笑','被调侃的你','化解尴尬、清楚表达边界、保住关系','哈哈，你最近又胖了吧？是不是天天加班点夜宵啊？','','online',1,NULL,'','["忍着不说", "当众发火", "开回对方的玩笑伤和气"]');
INSERT INTO "drill" VALUES(59,27,'朋友开口向你借钱','大学室友小罗打电话给你，说想创业，问你能不能借他五万块。你们关系不错，但你手头的钱另有安排，而且他之前借过别人的钱很久没还。请你真诚地拒绝，表达关心，避免伤害友谊，必要时提出你能提供的其他帮助。','','中压',3,'纯语音','大学室友小罗，很需要钱，被拒绝时会失落、试图说服你','被借钱的朋友','明确拒绝、不找假借口、表达关心并保住关系','喂，兄弟，在忙吗？我有个事想找你商量……能不能先借我五万块？','','online',0,NULL,'','["编一个假理由", "拖着不回复", "拒绝后不再关心对方"]');
INSERT INTO "drill" VALUES(60,28,'行业活动上和陌生人搭话','你参加一场行业交流会，茶歇时站在你旁边的是一位看起来比较资深的人，正在看手机。你想认识他，拓展人脉。请你自然地开启对话，找到共同话题，让对方愿意继续聊下去，最后交换联系方式。','','低压',3,'纯语音','资深从业者周先生，礼貌但有距离感，聊到感兴趣的话题会打开','参会者','点燃话题：同频、复述、延展、提问；自然自我介绍','（抬头看了你一眼）嗯？','','online',0,NULL,'','["一上来就推销自己", "查户口式连环提问", "聊完不留联系方式"]');
INSERT INTO "drill" VALUES(61,29,'第一次给强势的新老板汇报','公司来了一位新的业务副总冯总，雷厉风行，开会经常打断别人：“说重点！”今天你要第一次向他汇报你负责的项目，你准备了很多背景材料。请你根据他的风格调整汇报方式，结论先行，用数据和结果说话，在 2 分钟内讲清楚。','','高压',3,'纯语音','新副总冯总，D 型性格：急、要结果、讨厌铺垫，会频繁打断','项目负责人','看人说话：对 D 型领导直截了当、结论先行、讲结果','坐。我十分钟后还有会，直接说结果。','','online',0,NULL,'','["从项目背景讲起", "被打断后慌乱", "只讲过程不讲结果"]');
INSERT INTO "drill" VALUES(62,30,'给妈妈打电话，说出一直没说的感谢','今天是妈妈的生日，你在外地工作没能回家。你一直想对她说些感谢的话，但平时总是不好意思开口。请你在这通电话里，用具体的回忆和细节表达对妈妈的感谢和爱，而不只是“生日快乐”。妈妈可能会害羞地岔开话题，请你温和地把话说完。','','低压',3,'纯语音','妈妈，接到电话很开心，被表达感谢时会不好意思、习惯性地关心你吃饭和工作','在外地工作的子女','用具体细节表达情感、坦然说出爱与感谢','喂？哎呀，这么晚还打电话，吃饭了没有？','','online',0,NULL,'','["只说“生日快乐”", "被妈妈岔开话题就放弃", "说着说着变成汇报工作"]');
INSERT INTO "drill" VALUES(63,30,'结婚纪念日，对伴侣说声谢谢','今天是你们结婚五周年纪念日。这一年你工作很忙，家里的事大多是伴侣在操持。晚饭时，你想认真地对 TA 表达感谢。请你用具体的事情说出 TA 的付出，以及这些事对你的意义，而不只是“辛苦了”。','','低压',3,'纯语音','你的伴侣，有些疲惫，起初会说“没什么”，被认真对待后会感动','工作繁忙的一方','具体表达感谢、说出对方付出的意义、表达承诺','今天怎么这么早回来？还买了花……怎么了，突然这么正式？','','online',1,NULL,'','["只说“辛苦了”", "边说边看手机", "说完马上转移话题"]');
INSERT INTO "drill" VALUES(64,31,'伴侣抱怨你总是加班不陪 TA','这个月你连续加班到很晚，今晚又错过了约好的晚饭。伴侣在家等你，一见面就说：“你心里还有这个家吗？”请你先接住对方的情绪，不急着辩解，表达理解和歉意，再一起商量以后怎么安排，让争吵变成沟通。','','中压',3,'纯语音','委屈的伴侣，情绪激动，一开始会翻旧账，被理解后会软化','经常加班的一方','先处理情绪、不辩解不指责、共同找解决办法','你还知道回来？说好今天一起吃饭的，你心里到底还有没有这个家？','','online',0,NULL,'','["“我加班不也是为了这个家”", "翻对方的旧账", "只道歉不给具体改变"]');
INSERT INTO "drill" VALUES(65,31,'伴侣回家抱怨被领导针对','伴侣下班回家，一进门就说：“我们领导今天又当着全组的面批评我，他根本不了解一线情况！气死我了！”你的第一反应是想说“职场都这样，忍忍吧”。请你先接住对方的情绪，鼓励他说下去，表达理解，最后再问需不需要你帮忙，而不是急着讲道理。','','低压',3,'纯语音','你的伴侣，非常委屈生气，如果你讲道理或帮领导说话会更生气','伴侣','情绪降级：接纳情绪、鼓励分享、表达理解、共同策划','气死我了！我们领导今天又当着全组的面批评我，他根本就不了解一线！','','online',1,NULL,'','["“职场都这样，忍忍吧”", "帮领导说话“他也有压力”", "急着给建议“你应该……”"]');
INSERT INTO "drill" VALUES(66,31,'伴侣经常晚归，你想好好谈谈','这个月伴侣有一大半时间都是十一点后才回家，回来就玩手机，你们几乎没有好好说过话。你心里积了很多委屈，但不想吵架。今晚你决定好好谈一次。请你用不指责的方式说出事实、感受和需要，并提出一个具体的请求。','','中压',3,'纯语音','你的伴侣，工作确实忙，被指责时会防御：“我加班不也是为了这个家吗？”','伴侣','非暴力沟通：事实、感受、需要、请求','怎么还没睡？有什么事吗？我今天真的很累。','','online',2,NULL,'','["“你从来都不顾家”", "翻旧账", "提的要求太模糊“你能不能上点心”"]');
INSERT INTO "drill" VALUES(67,32,'春节饭桌上被亲戚追问工资和对象','春节家族聚餐，二姨当着一桌亲戚问你：“现在一个月挣多少啊？有对象了没有？都这么大了还不着急？”大家都看着你。请你得体地回应，不透露不想说的隐私，也不顶撞长辈，巧妙地转移话题，让场面保持和气。','','中压',2,'纯语音','热心的二姨，会连续追问，还会拿别人家孩子比较','回家过年的年轻人','礼貌设立边界、幽默回应、转移话题','哎呀，好久不见！现在一个月挣多少啊？有对象没有？都这么大了还不着急？','','online',0,NULL,'','["当众顶撞", "认真报数字", "被比较后生闷气"]');
INSERT INTO "drill" VALUES(68,32,'告诉父母你想去外地发展','你在老家有一份稳定的工作，但拿到了一个去上海发展的机会，你很想去。父母一直希望你留在身边。今晚你打算跟他们摊牌。请你说明你的想法和规划，理解父母的担心，给他们具体的安心承诺，争取他们的理解和支持。','','中压',4,'纯语音','你的父亲，传统、担心你在外吃苦，起初强烈反对','想去外地发展的子女','说清规划、共情父母担忧、给出具体承诺','去上海？老家这份工作多稳定，你折腾什么？我和你妈年纪也大了。','','online',1,NULL,'','["先斩后奏", "被反对后吵起来", "没有具体安排让父母安心"]');
INSERT INTO "drill" VALUES(69,32,'劝婆婆别总给孩子吃冰激凌','孩子最近咳嗽，医生说不能吃冷饮，但婆婆心疼孙子，总是偷偷给他买冰激凌。你想和婆婆沟通这件事，但不想伤了婆婆的心，也不想让家里关系紧张。请你用尊重和温和的方式说明情况，提出具体的请求。','','中压',3,'纯语音','婆婆，疼孙子，觉得“吃一点没关系”，被说多了会觉得委屈','儿媳','温柔法则 + 非暴力沟通：先肯定、讲事实、提请求','怎么了？我又没给他吃多少，就一小口。','','online',2,NULL,'','["当着孩子的面说婆婆", "让老公去传话", "语气指责“您怎么又给他吃”"]');
INSERT INTO "drill" VALUES(70,33,'和孩子商量每天玩手机的时间','你 10 岁的孩子最近每天放学都抱着手机玩游戏，作业拖到很晚。你想和他商量一个每天玩手机的规则，而不是直接没收。请你用温柔而坚定的方式，先理解他，再和他一起定规则，让他愿意遵守。','','中压',3,'纯语音','10 岁的孩子，一听要限制手机就抗拒，会讨价还价','家长','温柔法则：命令变商定、理解需求、一起定规则','妈妈你又要说手机的事吗？我作业一会儿就写！','','online',0,NULL,'','["直接没收手机", "说教“玩手机会变笨”", "规则定了自己不遵守"]');
INSERT INTO "drill" VALUES(71,33,'孩子考试没考好，回家很沮丧','孩子期中考试数学只考了 68 分，回家后一直躲在房间里不出来。你敲门进去，看到他眼睛红红的。请你先接住孩子的情绪，让他感到被理解和支持，再和他一起找原因，而不是批评。','','低压',2,'纯语音','孩子，害怕被骂、很沮丧，一开始不愿意说话','家长','先处理情绪：共情、关爱，再一起找原因','（小声）……别问了，我考砸了。','','online',1,NULL,'','["一进门就问“怎么又没考好”", "和别的孩子比较", "说“没关系”但脸色很难看"]');
INSERT INTO "drill" VALUES(72,34,'客户来电投诉产品质量','你是一家家电品牌的客服主管。客户黄先生买的空调安装不到一周就不制冷，售后两次上门都没修好，他打电话来非常愤怒，要求退货并赔偿，否则就去网上曝光。请你先安抚情绪、表达共情，再了解诉求，在公司政策范围内给出解决方案。','','高压',4,'纯语音','愤怒的客户黄先生，语气激烈、会打断你、威胁投诉曝光，被真诚对待后会逐渐缓和','家电品牌客服主管','先处理情绪再处理事情、共情倾听、给出具体解决方案','你们到底还管不管了？！空调买了不到一周就不制冷，修了两次都没修好，大热天的我家孩子都中暑了！今天必须给我退货赔钱，不然我就去网上曝光你们！','','online',0,NULL,'','["一上来讲政策条款", "推给售后部门", "说“您别激动”"]');
INSERT INTO "drill" VALUES(73,34,'顾客投诉上错菜还等了 40 分钟','你是一家餐厅的店长。一桌客人等了 40 分钟才上菜，结果还上错了一道，顾客拍着桌子要见负责人。请你先道歉安抚，了解诉求，在你的权限内给出补偿方案（如免单这道菜、赠送饮品、优先出餐），把一次投诉变成回头客。','','中压',3,'纯语音','生气的顾客，带着朋友来吃饭觉得丢面子，被诚恳对待后会缓和','餐厅店长','快速道歉、共情、给出具体补偿、挽回体验','你就是店长？等了四十分钟！还上错菜！我带朋友来吃饭，你让我脸往哪搁？','','online',1,NULL,'','["解释后厨太忙", "让服务员背锅", "补偿太小显得没诚意"]');
INSERT INTO "drill" VALUES(74,35,'小剐蹭，对方情绪激动','下班高峰，你开车并线时和旁边车道的车发生了轻微剐蹭，双方车辆都只是掉了点漆。对方车主下车后很激动，认为全是你的责任，要求你赔 2000 元私了。你认为双方都有责任。请你保持冷静，先确认安全，再理性沟通，提出合理的处理方式（如报警、走保险或协商金额）。','','高压',3,'纯语音','对方车主，着急赶时间、情绪激动，坚持是你全责','发生剐蹭的车主','情绪稳定、讲事实不指责、提出合理的解决路径','你怎么开车的？！并线不看后视镜啊？你看把我车蹭成什么样了！你全责，赔两千私了，我还赶时间呢！','','online',0,NULL,'','["跟着吵起来", "当场认全责", "答应高额私了"]');
INSERT INTO "drill" VALUES(75,36,'被同事误会抢功劳','上周的季度汇报上，你介绍了项目成果，但同事小郑认为你把他负责的部分说成是你自己做的，现在他对你很冷淡，还在别人面前抱怨。你其实在汇报时提到了团队，只是没有点他的名字。请你主动找他沟通，澄清误会，承认疏忽，修复关系。','','中压',3,'纯语音','同事小郑，心里有委屈，一开始冷淡、带刺，被真诚对待后会软化','做季度汇报的同事','主动沟通、先认可对方感受、澄清事实、承认不足','（头也不抬）有事吗？我挺忙的。','','online',0,NULL,'','["急着证明自己没错", "在别人面前解释", "不承认疏忽"]');
INSERT INTO "drill" VALUES(76,36,'领导误会你上班摸鱼','你上午在工位上用手机和客户沟通方案，被路过的领导看到。下午领导把你叫到办公室：“最近工作状态不太对啊，上班总看手机？”请你冷静地澄清事实，拿出证据，同时接受领导的关注，顺势汇报你的工作进展，扭转印象。','','中压',3,'纯语音','部门领导，先入为主，起初不太相信你的解释','被误会的员工','不急不躁地澄清、用事实说话、顺势展示工作成果','坐。我最近看你上班老拿着手机，工作状态是不是不太对啊？','','online',1,NULL,'','["委屈地辩解", "说“我没有”就没下文", "从此不敢碰手机"]');
INSERT INTO "drill" VALUES(77,37,'楼上深夜噪音，上门沟通','楼上邻居最近每晚十一点后还有拖椅子、小孩跑跳的声音，你已经连续一周没睡好。今晚你决定上楼敲门沟通。请你礼貌地说明情况和影响，避免指责，倾听对方的难处，一起商量可行的解决办法（如铺地垫、约定时间）。','','中压',3,'纯语音','楼上的年轻妈妈，一开始有防御心，觉得“小孩跑跳很正常”','被噪音困扰的楼下住户','描述影响不指责、理解对方、达成具体约定','（开门）你好，有什么事吗？这么晚了。','','online',0,NULL,'','["半夜带着火气敲门", "说“你们家太没素质”", "只抱怨不提方案"]');
INSERT INTO "drill" VALUES(78,38,'答应客户的事没做到，打电话道歉','你答应客户周三前发出样品，结果因为内部沟通失误拖到了周五，客户的展会因此没能用上你们的样品，非常不满。请你给客户负责人打电话道歉：说中对方真正在意的点，承担责任，给出补救方案，重建信任。','','高压',3,'纯语音','客户负责人方总，很失望，会说“你们太不靠谱了”，听到真诚和补救后会缓和','供应商客户经理','有效道歉：说中情绪点、承担责任、补救、承诺','你们还好意思打电话来？展会都结束了，样品才到，你们太不靠谱了！','','online',0,NULL,'','["解释“物流出了问题”", "说“您别生气”", "只道歉不给补偿"]');
INSERT INTO "drill" VALUES(79,38,'忘了伴侣的生日','昨天是伴侣的生日，你因为加班完全忘了，直到今天早上看到对方朋友圈才想起来。伴侣一整天都没理你。晚上回家，你要好好道个歉。请你说中对方真正难过的点，不找借口，并用行动弥补。','','中压',3,'纯语音','你的伴侣，很失望，觉得自己不被重视，一开始冷淡','伴侣','有效道歉：不说“别生气”，说中对方在意的点','（冷淡）回来了。饭在锅里，自己热。','','online',1,NULL,'','["“我太忙了你也知道”", "“别生气了，我补给你”", "只买礼物不道歉"]');
INSERT INTO "drill" VALUES(80,39,'供应商要求涨价 15%','你是公司的采购经理。合作三年的包装材料供应商何总找你，说原材料涨价，要求从下个月起涨价 15%，否则只能减少供货。你的预算最多能接受 5% 的涨幅。请你了解对方的真实困难，挖掘双方的利益点（如签长期合同、增加订量、调整付款周期），谈出一个双方都能接受的方案。','','中压',4,'纯语音','供应商何总，确实面临成本压力，立场坚定但愿意谈条件','公司采购经理','探询对方真实需求、交换条件、创造双赢方案','王经理，咱们合作三年了，我就直说吧。今年原材料涨得太厉害，下个月开始我们得涨价 15%，不然真的做不下去了。','','online',0,NULL,'','["直接接受涨价", "一口回绝谈崩", "不问对方真实成本压力"]');
INSERT INTO "drill" VALUES(81,39,'房东要求续租涨价 20%','你租的房子马上到期，房东打电话说续租要涨 20% 的房租。你很喜欢这套房子，也一直按时交租、爱护房屋。你的预算最多接受涨 8%。请你了解房东涨价的原因，强调你作为好租客的价值，提出交换条件（如签两年、一次付半年），谈一个双方都满意的价格。','','中压',3,'纯语音','房东林阿姨，觉得周边都涨了，但也怕换租客麻烦','想续租的租客','了解对方动机、展示自身价值、用条件交换价格','小王啊，房子下个月到期了。我跟你说一下，续租的话房租要涨 20%，周边都涨了。','','online',1,NULL,'','["一听涨价就说要搬", "只讲自己困难", "让步太快"]');
INSERT INTO "drill" VALUES(82,39,'和合作伙伴谈分成比例','你们公司做了一款课程产品，一个拥有 50 万粉丝的博主邓老师有意合作推广。对方要求销售额五五分成，你们的底线是三七分（你们七）。请你了解对方的诉求，说清你们投入的成本和价值，设计一个阶梯分成或保底+分成的方案，促成长期合作。','','中压',4,'纯语音','博主邓老师，清楚自己的流量价值，立场坚定但愿意听方案','课程公司的商务负责人','锚定价值、设计灵活方案、为长期合作留空间','你们的课我看了，内容不错。不过我这边的报价是五五分成，这是我合作的惯例。','','online',2,NULL,'','["直接答应对方的比例", "只谈比例不谈总盘子", "不设保底条款"]');
INSERT INTO "drill" VALUES(83,40,'客户一上来就问“多少钱”','你是一家装修公司的设计顾问，一位客户刚进店，还没看方案就问：“你们全包多少钱一平？”你知道直接报价很容易被拿去比价。请你先不报价，通过提问了解客户的需求和预算，再给出有针对性的报价区间。','','中压',3,'纯语音','客户张先生，精明、在比价，会坚持要先听价格','装修公司设计顾问','先问后报：问痛点、说重点、答保障；报价高开低走','别的先不说，你们全包多少钱一平？','','online',0,NULL,'','["直接报最低价", "被追问就慌着报价", "报一个数没有区间和理由"]');
INSERT INTO "drill" VALUES(84,40,'采购压价，要你再降 10%','你是供应商的销售，和客户的采购经理谈年度合同。你的报价已经是比较合理的价格了，对方却说：“别家比你便宜 10%，你们不降价我们就换了。”你知道对方更看重你们的交期和质量。请你守住价格，不轻易让步，如果让步必须换取条件。','','高压',4,'纯语音','客户采购经理，强势压价，会用“别家更便宜”施压','供应商销售','有条件让步、三张牌：请示领导、交换条件、越让越小','别家比你们便宜 10%，你们要是不降，今年的单子我们就给别人了。','','online',1,NULL,'','["一被压价就降", "无条件让步", "一次让到底"]');
INSERT INTO "drill" VALUES(85,40,'谈判僵住了，对方寸步不让','你代表公司和一家合作方谈渠道分成，已经谈了一个多小时，对方坚持六四分成（他们六），你方底线是五五。双方都不肯让，气氛有点僵。请你打破僵局：先处理气氛，再换一个角度或条件（时间、范围、权限）推动谈判，避免谈崩。','','高压',4,'纯语音','合作方代表，立场坚定，对你的方案不置可否，会说“那就没得谈了”','公司商务代表','打破僵局：处理心情、换时间/空间/角度、有条件交换','我们的条件很清楚，六四，少一点都不行。你们要是做不了主，那就算了。','','online',2,NULL,'','["跟着对方情绪对抗", "为了不谈崩直接答应", "一直在一个条件上来回拉锯"]');
INSERT INTO "drill" VALUES(86,41,'临时点名发言不慌乱，展现临场应变与表达力','你是公司销售部的一名员工，正在参加季度项目复盘会，会议主题是“如何提升下一季度的客户转化率”。领导讲到改进方案时突然点名：“小李，你接触客户比较多，说说你的看法。”毫无准备的你，请使用“即兴发言2步走”“即兴演讲4大公式”快速整理思路，在1分钟内说出自己的观点和建议。','','低压',3,'纯语音','销售部领导王总，主持复盘会，友善但会追问建议的可执行性','销售部员工小李','即兴发言结构（先表态再展开，如“观点—原因—案例—总结”）、1 分钟内清晰表达','小李，你接触客户比较多，说说你的看法？下个季度咱们的转化率怎么提上去？','','online',0,NULL,'','["说“我没想好”", "讲太多跑题", "重复别人的观点"]');
INSERT INTO "drill" VALUES(87,41,'公司年会上被突然叫上台说两句','公司年会，你所在的团队刚获得“年度优秀团队”奖。主持人突然把话筒递给你：“请团队代表说几句获奖感言！”台下坐着三百多人，包括公司高管。请你在 1 分钟内，用“感谢—回顾—展望”的结构说一段得体又有感染力的获奖感言。','','中压',2,'纯语音','年会主持人，热情地把话筒交给你，之后会追问一句“明年有什么目标”','获奖团队代表','即兴发言有结构、感谢具体、结尾有力','恭喜获得年度优秀团队！来，我们请团队代表上台说几句获奖感言，大家掌声欢迎！','','online',1,NULL,'','["只谢领导", "讲成述职", "紧张到语速飞快"]');
INSERT INTO "drill" VALUES(88,41,'培训结束，被点名谈收获','公司组织了一天的“高效沟通”培训，结束前讲师突然说：“请这位同学来分享一下今天的收获。”全场 50 人看着你。请你在 1 分钟内讲清楚：你收获了什么、有什么启发、接下来打算怎么做。','','低压',2,'纯语音','培训讲师，鼓励你分享，结束后会追问一句“具体会怎么用”','参训员工','霍启东：收获-启发-行动；感言就地取材','来，请这位同学分享一下今天的收获！','','online',2,NULL,'','["“收获很大，谢谢老师”就结束", "把一天内容复述一遍", "没有落到具体行动"]');
INSERT INTO "drill" VALUES(89,42,'项目受挫后，给团队打气','你带领的团队花了三个月准备的投标项目刚刚失败了，大家都很沮丧，有人开始怀疑方向。周一早会上，你需要对团队讲几句话。请你承认失败、肯定大家的付出、总结可以带走的收获，并明确下一步目标，让团队重新振作起来。','','中压',3,'纯语音','团队里的老员工阿峰，情绪低落、有些消极，会提出质疑','团队负责人','共情承认失败、肯定付出、给出希望与清晰的下一步','（叹气）老大，说实话，三个月白干了……大家现在都挺没劲的，你说咱们这方向到底还对不对？','','online',0,NULL,'','["假装没事“没关系，下次加油”", "找外部原因甩锅", "没有下一步"]');
INSERT INTO "drill" VALUES(90,42,'新项目启动会，给团队做动员','公司决定启动一个三个月的攻坚项目，目标是上线一款全新产品，你被任命为项目负责人。今天是启动会，团队里有新人也有老员工，有人兴奋也有人担心工作量。请你讲清楚项目的意义、目标和节奏，回应大家的担心，让团队对接下来的三个月充满信心。','','低压',3,'纯语音','团队成员代表小冯，会提出“三个月是不是太赶”之类的担心','项目负责人','讲清意义和目标、正视困难、给出具体支持','老大，我先说句实话哈，三个月上线一款新产品，大家心里都有点没底……','','online',1,NULL,'','["只讲目标不讲支持", "回避“太赶”的担心", "口号多、具体安排少"]');
INSERT INTO "drill" VALUES(91,42,'团队纪律松散，讲一段话改变大家','最近团队里不少人开会迟到、周报敷衍，你作为负责人要在周一例会上讲一段话。你不想只是批评，而是想讲一个故事，让大家从心里认同“要在没人盯的时候也把事做好”。请你用“故事-问题-理解-格局-信念-要求”的结构完成这段讲话。','','中压',3,'纯语音','团队老员工老许，觉得“大家都挺累的”，会小声嘀咕','团队负责人','信念萃取与植入：用故事带出信念，理解对方再扩大格局','（小声）又要开始训话了……','','online',2,NULL,'','["一开口就批评点名", "只讲道理没有故事", "要求太模糊“大家要自觉”"]');
INSERT INTO "drill" VALUES(92,43,'晋升答辩，评委追问你的不足','你正在参加公司的晋升答辩，刚讲完 10 分钟的述职，评委之一的技术总监冯总开始提问：“你说项目成功了，那你个人在里面到底起了什么作用？如果重来你会怎么做？”请你沉着回答，突出个人贡献，坦诚反思不足，展示你的成长和下一阶段的思考。','','高压',4,'纯语音','答辩评委冯总，犀利、注重个人贡献和反思能力，会连续追问','晋升候选人','说清个人贡献、坦诚反思、展示更高层级的思考','你的述职我听完了。你说这个项目成功了，那你个人在里面到底起了什么作用？','','online',0,NULL,'','["把功劳全归团队，说不清个人贡献", "被追问后自我否定", "只说成功不谈反思"]');
INSERT INTO "drill" VALUES(93,44,'活动嘉宾迟到，你要临时救场','你主持一场行业分享会，下一位嘉宾的航班延误了，还要 15 分钟才能到场，台下两百位观众在等待。请你临时串场：与观众互动、聊一聊今天的主题、或者请一位观众分享，把这 15 分钟自然地撑过去，并在嘉宾到达时顺利衔接。','','中压',3,'纯语音','现场一位活跃的观众，会接你的话，偶尔提出问题','活动主持人','冷静应变、与观众互动、自然衔接','（工作人员小声）主持人，下一位嘉宾航班延误，还要十五分钟才能到，你先撑一下！','','online',0,NULL,'','["直接宣布“嘉宾迟到了，大家等等”", "冷场干站着", "互动太长，嘉宾到了收不住"]');
INSERT INTO "drill" VALUES(94,45,'主持分享会开场，介绍嘉宾','你负责主持公司的季度分享会，今天请来的嘉宾是销售总监张伟，他带团队一个季度把业绩提升了 40%。台下 80 位同事。请你用 1-2 分钟完成开场：问好、欢迎点题、说明今天主题的重要性、塑造嘉宾、掌声有请。','','中压',2,'纯语音','现场一位同事，会在你提问时回应，嘉宾上台前会配合鼓掌','分享会主持人','主持开场：称-迎-重-人-请','（台下渐渐安静下来）','','online',0,NULL,'','["主持人讲太多抢风头", "介绍嘉宾念简历", "有请时没有停顿，掌声起不来"]');
INSERT INTO "drill" VALUES(95,46,'给新同事做 10 分钟内部分享','部门新来了 6 位同事，领导让你做一次 10 分钟的内部分享，主题是“如何写一份让领导满意的周报”。请你完成开场和第一个模块：破冰、导入痛点、点题、说明分几个部分，然后展开讲一个最重要的方法。','','中压',3,'纯语音','新同事代表小钟，会在你提问时回应，也会提一个问题','部门老员工','微课八步：破冰、导入、主题、目录、展开（是什么-为什么-怎么做-举例）','（新同事们坐好了，看着你）','','online',0,NULL,'','["一上来就讲内容，没人进入状态", "什么都想讲，每个都讲不透", "只讲道理没有例子和练习"]');
INSERT INTO "drill" VALUES(96,47,'录一条 1 分钟口播：介绍你的专业','你想在短视频平台做个人 IP，第一条视频要用 1 分钟介绍你擅长的一个专业技巧（比如时间管理、沟通、理财等任选）。编导会帮你“开拍”，并在你讲完后给出反馈、让你再来一版。请你用“钩子+三点”的结构，3 秒内抓住观众，再讲清三个要点。','','低压',3,'纯语音','短视频编导小林，专业直接，会指出“开头不够抓人”“第二点太长”并让你重录','想做个人 IP 的你','口播结构：黄金 3 秒钩子 + 三个要点 + 行动号召','好，我们准备开拍。你先想好要讲什么，3、2、1——开始！','','online',0,NULL,'','["开头先自我介绍，3 秒没进主题", "要点太多，讲不完", "没有行动号召"]');
INSERT INTO "drill" VALUES(97,47,'用一个反转故事讲你的失败经历','编导建议你拍一条“故事型”口播：讲一次你自己的失败经历，以及它带给你的改变。请你用“钩子-冲突-转折-金句”的结构，在 1 分钟内讲一个有画面、有反转的故事，最后用一句话点出观点。','','低压',3,'纯语音','短视频编导小林，会追问细节“当时具体发生了什么”，并提醒你加金句','想做个人 IP 的你','故事型口播：钩子、冲突、反转、金句','这次我们拍个故事。讲一次你搞砸的事，越具体越好。3、2、1，开始！','','online',1,NULL,'','["故事太长，铺垫一分钟", "没有细节，像在念总结", "结尾没有金句，观众记不住"]');
INSERT INTO "drill" VALUES(98,48,'直播时观众质疑你的观点','你在直播里分享“职场新人要敢于向领导提需求”，弹幕里一位观众说：“说得轻巧，提需求就被穿小鞋了，你就是站着说话不腰疼。”不少人跟着刷屏。请你冷静回应：承认对方说法的合理部分，再讲清你的观点和依据，最后把讨论引向建设性的方向。','','中压',3,'纯语音','直播间里情绪激动的观众，会继续追问“你自己做到了吗”','职场知识主播','天秤式观点：一方面-另一方面-平心而论；回答问题公式','（弹幕）说得轻巧，提需求就被穿小鞋了，你就是站着说话不腰疼！','','online',0,NULL,'','["和观众吵起来", "无视质疑继续讲", "被带节奏后改口"]');
INSERT INTO "drill_framework" VALUES(1,27,'张工，这个活动是这季度拉新的主战场（共同目标），我需要一个落地页（需求）。能不能先做一个简版，两天就够？',0);
INSERT INTO "drill_framework" VALUES(1,41,'先听出他的怨气是“市场部总临时加需求”，先认这个，再谈这一次。',1);
INSERT INTO "drill_framework" VALUES(2,6,'接口原定上周三交，现在晚了一周，影响的是下周五的上线。',0);
INSERT INTO "drill_framework" VALUES(2,56,'如果您这边周三前能先给核心的两个接口，剩下的我们可以晚两天接。',1);
INSERT INTO "drill_framework" VALUES(3,46,'我今年负责了两个重点项目，业绩超额 30%（事实）。不是对现在不满，是希望回报能和贡献匹配（对比说明）。您怎么看？',0);
INSERT INTO "drill_framework" VALUES(3,55,'先说一个比期望略高的数，留出商量空间；谈不动就谈晋升、培训或下半年复议。',1);
INSERT INTO "drill_framework" VALUES(4,30,'明白，这个分析确实重要。我手上季度报告周一要交，您看是先保报告，竞品分析周三给您框架？',0);
INSERT INTO "drill_framework" VALUES(4,27,'为了两件事都保证质量，我需要您帮我定一下优先级。',1);
INSERT INTO "drill_framework" VALUES(7,35,'这两次交付都晚了 3 天（事实）。最近是不是遇到什么困难了？（关怀）',0);
INSERT INTO "drill_framework" VALUES(7,33,'主题-了解经过-讲影响-给建议-约定下次检查时间。',1);
INSERT INTO "drill_framework" VALUES(8,38,'这次请你整理 30 份访谈，目的是找出用户最不满的三件事。周三先给我 10 份看方向，周五交完。你复述一下？',0);
INSERT INTO "drill_framework" VALUES(8,45,'有不懂的随时问我，问问题是好事。',1);
INSERT INTO "drill_framework" VALUES(9,33,'今天聊的是连续两个季度没达标的事。先听听你怎么看……我们一起定三个月的改进目标，每月碰一次。',0);
INSERT INTO "drill_framework" VALUES(9,41,'对方处于防御/对抗状态时，先别讲制度，先认他的资历和付出。',1);
INSERT INTO "drill_framework" VALUES(13,2,'两位说的都有道理。我们先回到今天的议题：定下个版本的三个核心功能。按钮颜色会后你们两位单独对一下，周五给结论。',0);
INSERT INTO "drill_framework" VALUES(13,41,'先肯定双方的出发点，再拉回议程。',1);
INSERT INTO "drill_framework" VALUES(14,11,'谢谢李总提醒。（停顿）您问的是口径——分母是活动期间的独立访客，去年同期用的是同一口径。',0);
INSERT INTO "drill_framework" VALUES(14,2,'回答完质疑，用一句话拉回结论：所以这个渠道值得追加预算。',1);
INSERT INTO "drill_framework" VALUES(17,92,'赵总早！我在做会员小程序，上线一个月用户 5 万了，下周有个复购活动。',0);
INSERT INTO "drill_framework" VALUES(17,48,'赵总您最近也在关注私域吗？',1);
INSERT INTO "drill_framework" VALUES(18,48,'你之前在杭州啊（复）？我也特别喜欢那边（同）。来这边住得还习惯吗？（问）',0);
INSERT INTO "drill_framework" VALUES(18,44,'刚来都这样，我第一周也找不到会议室。',1);
INSERT INTO "drill_framework" VALUES(19,24,'赵总，有个风险：核心供应商可能延期两周。方案一换备选，成本多 8 万；方案二跟客户谈延期。我倾向方案一，您看？',0);
INSERT INTO "drill_framework" VALUES(19,2,'结论先行，再讲原因、影响和需要的支持。',1);
INSERT INTO "drill_framework" VALUES(20,28,'上半年完成 115%；下半年目标再增长 30%，现有人手只能覆盖 20%。我申请两个编制，最低一个也能保住核心客户。',0);
INSERT INTO "drill_framework" VALUES(20,5,'用 1-2 个项目的 STAR 证明团队的产出。',1);
INSERT INTO "drill_framework" VALUES(23,32,'何总，我想跟您说一个决定……这几年您教会我最多的是做决策。交接清单我准备好了，一个月内交完。',0);
INSERT INTO "drill_framework" VALUES(23,43,'感谢要谢在具体的事上：那次项目是您带我熬过来的。',1);
INSERT INTO "drill_framework" VALUES(32,17,'各位贵宾晚上好！今天是我们合作的第三年……我提议，大家共同举杯！祝各位事业兴旺，干杯！',0);
INSERT INTO "drill_framework" VALUES(32,9,'感谢客户-回顾一起熬过的项目-展望明年。',1);
INSERT INTO "drill_framework" VALUES(33,7,'讲一个你们之间的真实小故事：他追她时的一次“翻车”，最后怎么打动她的。',0);
INSERT INTO "drill_framework" VALUES(33,17,'最后：我提议，大家一起举杯，祝新人百年好合，干杯！',1);
INSERT INTO "drill_framework" VALUES(34,48,'李先生也是小周的朋友？（问）我们是大学同学（延），你们是怎么认识的？',0);
INSERT INTO "drill_framework" VALUES(34,52,'小周每次请客都选这家，我怀疑他是这的股东。',1);
INSERT INTO "drill_framework" VALUES(35,48,'冯总，听说您年轻时也在一线跑过销售？那时候最难忘的客户是什么样的？',0);
INSERT INTO "drill_framework" VALUES(35,49,'夸具体的事：上次您在会上讲的那个案例，我们组现在还在用。',1);
INSERT INTO "drill_framework" VALUES(36,52,'孙总，小张一喝酒就开始说胡话，财务说的“疯”是忙疯了，您那三个月正好是我们最忙的季度。',0);
INSERT INTO "drill_framework" VALUES(36,42,'说中客户在意的点：这话让您觉得被冒犯了，是我们不对。',1);
INSERT INTO "drill_framework" VALUES(37,50,'陈总，我有个不情之请……您不用担保什么，只要帮我引荐认识一下，后面的我自己去谈。',0);
