INSERT INTO "drill_framework" VALUES(62,43,'妈，我记得高三那年你每天五点起来给我做早饭（做了什么），那一年我才撑下来（价值）。',0);
INSERT INTO "drill_framework" VALUES(62,9,'感谢-回忆细节-说说对未来的打算。',1);
