INSERT INTO "drill_framework" VALUES(72,40,'黄先生，大热天空调不制冷，孩子还中暑了，换谁都着急（接纳+理解）。',0);
INSERT INTO "drill_framework" VALUES(72,42,'两次都没修好是我们的问题。今天下午我安排主管带新机上门，退换您来选。',1);
