INSERT INTO "drill_framework" VALUES(6,28,'我理解现在现金流紧张。旺季我们超额 18%，但已经有 1 人提离职，再走一个，下月二期交付就危险了。我想申请 3 万激励，最低 2 万也能稳住核心三个人。',0);
INSERT INTO "drill_framework" VALUES(10,33,'对，今天就聊这件事。这次多花了 8000 运费，客户也投诉了。你觉得主要是什么原因造成的？……那下次发货前加一步双人核对，你看有什么困难？一个月后我们再看效果。',0);
