INSERT INTO "drill_framework" VALUES(11,34,'我理解你的担心，换谁都会犹豫。选你是因为你最懂我们的客户，线上线下都会的人，三年后路会宽很多。收入这块前三个月我给你保底。你考虑一下，周五前给我答复。',0);
INSERT INTO "drill_framework" VALUES(12,40,'听起来你这几天特别累（接纳）。客户具体是哪里不满意？（分享）……换我也会怀疑自己（理解）。我们一起把客户的反馈拆一下，下一版我陪你过一遍？（策划）',0);
INSERT INTO "drill_framework" VALUES(12,37,'这三版我都看了，数据部分其实越来越扎实，问题出在客户还没想清楚自己要什么。',1);
INSERT INTO "drill_framework" VALUES(15,15,'人都到齐了，我们开始。今天一小时，先 10 分钟过进度，再讨论两件事：活动预算和新人培训。目标是会后两件事都有结论。辛苦大家手机先静音。',0);
INSERT INTO "drill_framework" VALUES(15,2,'第一个议题，结论先说：我建议预算控制在 5 万以内，原因有三点……',1);
INSERT INTO "drill_framework" VALUES(16,2,'我今天有三件事：改客户 A 的方案、跟财务对账、下午面试一个候选人。对账需要小王 3 点前把发票给我。',0);
INSERT INTO "drill_framework" VALUES(16,23,'方案今天下班前出第二版；对账有一笔 2 万的差额还在查，可能有风险。',1);
INSERT INTO "drill_framework" VALUES(21,26,'好的张总，确认两点：是给渠道商看的合作方案，还是我们内部用的谈判要点？您周几见？我周三先给您一版框架。',0);
INSERT INTO "drill_framework" VALUES(22,24,'刘总，支付出了故障，一小时内约 300 笔订单失败。方案一切备用通道，10 分钟能恢复但手续费高 0.2%；方案二等第三方修复，时间不确定。我倾向先切备用通道，您看可以吗？',0);
INSERT INTO "drill_framework" VALUES(22,6,'九点左右开始，影响的是全部线上订单，原因初步是第三方接口超时。',1);
INSERT INTO "drill_framework" VALUES(24,29,'您批评得对，这个错不只是 2 万块的事，是让公司在客户面前显得不专业。我已经想好了补救办法……也想借这个机会问问您，还有哪些地方需要我改进？',0);
INSERT INTO "drill_framework" VALUES(24,42,'是我没有做最后一遍核对，这是我的问题，不是系统的问题。',1);
INSERT INTO "drill_framework" VALUES(25,31,'刘姐，我下周三四要请两天假，家里有点事。我知道那周要交付，测试报告我周二前交，对接人小陈来盯，每天晚上我同步一次进度。',0);
INSERT INTO "drill_framework" VALUES(26,53,'马哥，今天真不行，我这方案六点前要交，老板等着呢。月报怎么填我可以给你 5 分钟讲一下，你自己弄会更快。',0);
INSERT INTO "drill_framework" VALUES(26,41,'我看你也挺急的，是不是今天被催了？',1);
INSERT INTO "drill_framework" VALUES(27,6,'我提供的是周一导出的原始数据，我刚核对过是对的；差异出在汇总表第三列的公式。',0);
INSERT INTO "drill_framework" VALUES(27,8,'现在的问题是客户手上的报表有误，我建议今天先由我和小郑一起重算一版发给客户，之后汇总表加一步交叉核对。',1);
INSERT INTO "drill_framework" VALUES(28,39,'今天会上讲的竞品分析，是我这两周做的（事实）。听到没提我的名字，我挺失落的（感受），因为我也希望领导看到我的工作（需要）。下次汇报能说明一下分工吗？（请求）',0);
INSERT INTO "drill_framework" VALUES(28,23,'以后重要的工作，我也会每周主动给领导同步进度。',1);
INSERT INTO "drill_framework" VALUES(29,59,'我们先回到目标：这次活动最重要的是拉新还是提升品牌好感？……明白，那我们先确认大方向，是主题创意不对，还是执行形式不对？',0);
INSERT INTO "drill_framework" VALUES(29,58,'您想要的是年轻人愿意转发的效果（目）。现在方案偏传统（现），我们准备了一个更社交化的版本（方），要不先看这个方向的草图？（行）',1);
INSERT INTO "drill_framework" VALUES(30,56,'理解，您这边也是被老板催的。两个页面大概多一周工作量，要么我们把原定的数据大屏挪到二期，要么走个需求变更，我帮您争取按成本价。',0);
INSERT INTO "drill_framework" VALUES(30,26,'我先确认一下，这两个页面是什么时候要？需要和现有的风格一致吗？',1);
INSERT INTO "drill_framework" VALUES(31,54,'孙总您好，我是××的小周，就占您一分钟。想请教一下，咱们今年中层管理者的培训，最想解决的是什么问题？',0);
INSERT INTO "drill_framework" VALUES(31,92,'我们专门帮企业中层提升沟通效率，上个月刚给××公司做完，他们跨部门会议时间少了 30%。',1);
INSERT INTO "drill_framework" VALUES(47,63,'我的缺点是不太会拒绝别人。以前同事找我帮忙我都答应，结果自己的工作经常延期。后来我每天先排好自己的优先级，帮忙前先说清楚能给多少时间。这半年基本没再延期过。',0);
INSERT INTO "drill_framework" VALUES(48,65,'这段时间我做了两件事：一是接了三个品牌的自由项目，二是系统学了数据分析，拿到了证书。也正因为这段时间想清楚了，我更确定要在成熟团队里把增长做深，这也是我来面试咱们公司的原因。',0);
INSERT INTO "drill_framework" VALUES(49,66,'这个问题我之前没有专门准备过，我先说说初步想法。第一个月我会做三件事：了解现有数据、访谈当地客户、找出一个最可能突破的国家……',0);
INSERT INTO "drill_framework" VALUES(49,4,'总的来说就是：先摸清、再聚焦、后试点。',1);
INSERT INTO "drill_framework" VALUES(50,5,'去年双十一（S），我负责把活动转化率从 2% 提到 3%（T）。我做了三版落地页 AB 测试，重写了客服话术（A），最后做到 3.4%，多卖了 120 万（R）。',0);
INSERT INTO "drill_framework" VALUES(50,64,'我们行业大促的平均转化率在 2.5% 左右。',1);
INSERT INTO "drill_framework" VALUES(51,68,'我先补充一点：刚才说到数据分析，我自己写过一个自动化报表工具，帮团队每周省了 4 个小时。另外想了解一下，如果我入职，您对我前三个月最大的期待是什么？',0);
INSERT INTO "drill_framework" VALUES(56,50,'刘姐您好，我是 15 级的学弟王磊，做了 5 年市场。看到咱们公司在招品牌经理，想请您帮忙内推一下，简历和岗位匹配说明我都整理好了，您转发就行，完全不用有压力。',0);
INSERT INTO "drill_framework" VALUES(56,18,'我之前在××负责过一个从 0 到 1 的品牌项目，半年做到行业前三。',1);
INSERT INTO "drill_framework" VALUES(60,48,'您好，刚才那场分享您觉得怎么样？我觉得讲私域那部分特别实在（同），您是做哪个方向的？（问）',0);
INSERT INTO "drill_framework" VALUES(60,18,'我是做新媒体运营的王磊，之前把一个账号从 0 做到 50 万粉，这次来想多认识做私域的朋友。',1);
INSERT INTO "drill_framework" VALUES(61,47,'（D 型）冯总，结论：项目进度正常，Q3 能上线，目前需要您拍板一件事——预算追加 10 万。',0);
INSERT INTO "drill_framework" VALUES(61,2,'理由有三个：……',1);
INSERT INTO "drill_framework" VALUES(65,40,'听起来你今天真的被气坏了（接纳）。他具体怎么说的？（分享）……当着全组的面确实太伤人了（理解）。你想怎么处理，要不要我陪你想想？（策划）',0);
INSERT INTO "drill_framework" VALUES(65,44,'换我也受不了，你已经比我能忍多了。',1);
INSERT INTO "drill_framework" VALUES(66,39,'这周你有五天都是十一点后回来（事实），我挺失落的（感受），因为我希望我们每天能有一点说话的时间（需要）。以后每周能有三天八点前回家吗？（请求）',0);
INSERT INTO "drill_framework" VALUES(66,45,'老公，我知道你是为了这个家，我们一起想个办法好不好？',1);
INSERT INTO "drill_framework" VALUES(69,45,'妈，我知道您最疼他了，他也最黏您。',0);
INSERT INTO "drill_framework" VALUES(69,39,'这周他咳嗽一直没好（事实），我挺担心的（感受），医生说要两周不碰冷饮（需要）。这两周您帮我盯着点，咱们给他买点水果好吗？（请求）',1);
INSERT INTO "drill_framework" VALUES(70,45,'宝贝，妈妈知道玩游戏很开心，我小时候也喜欢玩。我们一起商量个规则好不好？',0);
INSERT INTO "drill_framework" VALUES(70,58,'你想每天都能玩（目），现在作业写到太晚，第二天起不来（现）。要不先写完作业再玩 40 分钟（方），我们先试一周？（行）',1);
INSERT INTO "drill_framework" VALUES(71,44,'妈妈看到你很难过，难过是可以的，妈妈陪着你。',0);
INSERT INTO "drill_framework" VALUES(71,45,'我们一起看看错在哪里好不好？找到原因，下次就有办法了。',1);
INSERT INTO "drill_framework" VALUES(78,42,'方总，这次让您在展会上没有样品可用，影响的是您的客户和您的面子，这是我们的责任（说中+承担）。我们已经安排……（补救），以后所有交期我每周给您同步一次（承诺）。',0);
INSERT INTO "drill_framework" VALUES(78,29,'您说得对，靠谱是我们合作的基础，这次我们没做到。',1);
INSERT INTO "drill_framework" VALUES(79,42,'对不起，我知道你难过的不是生日本身，是觉得自己在我心里不重要（说中）。是我的问题，加班不是借口（承担）。这周六我订了你一直想去的那家餐厅（补救），以后重要的日子我都设好提醒（承诺）。',0);
INSERT INTO "drill_framework" VALUES(83,54,'张先生，价格我一定给您。为了报得准，想先问两个问题：房子多大？您最在意的是环保、工期还是预算？',0);
INSERT INTO "drill_framework" VALUES(83,55,'按您说的中等档次，我们的区间是 1200 到 1600 一平，我推荐您看 1400 这档，因为……',1);
INSERT INTO "drill_framework" VALUES(84,56,'价格确实没有空间了，这已经是我们给老客户的价。您看这样，我回去请示一下领导……领导说如果签两年并且预付 30%，可以再让 3%。',0);
INSERT INTO "drill_framework" VALUES(84,57,'如果您今年能把下半年的量一起定下来（空间），我们可以把交期从 15 天压到 10 天。',1);
INSERT INTO "drill_framework" VALUES(85,57,'我理解您的立场（处理心情）。咱们换个思路：第一年按五五，第二年销量过 1000 万后按六四（时间牌），您看呢？',0);
INSERT INTO "drill_framework" VALUES(85,56,'这个已经超出我的权限，我需要请示一下，但我先跟您确认，如果……您这边能接受吗？',1);
INSERT INTO "drill_framework" VALUES(88,10,'今天最大的收获是“结论先行”（收获）。我发现自己以前汇报总从背景讲起（启发）。从明天的周报开始，我第一句就写结论（行动）。',0);
INSERT INTO "drill_framework" VALUES(88,21,'印象最深的是上午那个练习，我同桌一分钟就把一件复杂的事讲清楚了。',1);
INSERT INTO "drill_framework" VALUES(91,96,'我想先讲个故事……人和人的差距，是在没人约束的时候拉开的。最近我们有些同事开会会迟到，我非常理解，大家确实很累。但是……所以希望大家记住……我要求大家做到……只有这样，我们才能……',0);
INSERT INTO "drill_framework" VALUES(91,71,'故事要有细节和转折，结论就是你要植入的那句话。',1);
INSERT INTO "drill_framework" VALUES(94,15,'各位同事大家好！欢迎来到季度分享会，我是主持人小李。最近大家是不是都在为业绩发愁？今天的嘉宾带团队一个季度把业绩提升了 40%……让我们掌声有请——张伟总监！',0);
INSERT INTO "drill_framework" VALUES(94,19,'（提问式）先问大家一个问题：这个季度完成目标的请举手？',1);
INSERT INTO "drill_framework" VALUES(95,95,'先问大家：想不想写周报时不再挤牙膏？（停顿，等回应）想的请举手！……今天我想和大家谈一谈：一份让领导满意的周报怎么写。我分三部分讲：结论先行、数据说话、带着下周计划……',0);
INSERT INTO "drill_framework" VALUES(95,22,'今天 10 分钟，讲完你能拿走一个周报模板。',1);
INSERT INTO "drill_framework" VALUES(96,81,'你是不是一被领导点名就脑子一片空白？今天教你三招：第一……第二……第三……收藏起来，下次开会用。',0);
INSERT INTO "drill_framework" VALUES(96,92,'我是××，专门帮职场人练习说话，三年帮 2000 人通过了晋升答辩。',1);
INSERT INTO "drill_framework" VALUES(97,82,'我第一次给老板汇报，被他打断了三次……从那以后我每次汇报第一句都说结论。汇报不是讲你做了多少，是讲你想让对方知道什么。',0);
INSERT INTO "drill_framework" VALUES(97,7,'先把当时的难讲足，再讲你做了什么，最后讲结果。',1);
INSERT INTO "drill_framework" VALUES(98,93,'这位朋友说得有道理，一方面确实有领导会不舒服；另一方面，不说出来，领导永远不知道你要什么。平心而论，关键不是提不提，而是怎么提。',0);
INSERT INTO "drill_framework" VALUES(98,11,'谢谢这位朋友的问题。（停顿）你担心的其实是提需求的风险……',1);
INSERT INTO "framework" VALUES(1,'prep','PREP 观点表达法','结构表达','先亮观点，再给理由和例子，最后回到观点，1 分钟把话说清楚。','[{"key": "P", "name": "观点 Point", "desc": "第一句就表态：我认为……"}, {"key": "R", "name": "理由 Reason", "desc": "给 1-3 个理由，最好带数字：主要有两个原因……"}, {"key": "E", "name": "案例 Example", "desc": "用一个具体的事例或数据证明"}, {"key": "P", "name": "重申观点 Point", "desc": "回扣开头，可加一句行动建议"}]','被问看法、会议发言、临时点名、回答“你怎么看”','我认为下季度应该先抓老客户复购。原因有两个：老客户转化成本只有新客的三分之一；我们复购率比行业低 8 个点。比如上月我跟进的 5 个老客户，回访一次就成交了 2 个。所以建议先做一轮老客户回访。','["铺垫太长，半天不进观点", "理由太多太散，超过 3 个就记不住", "只有道理没有例子，听起来很空"]','["先说“我的观点是……”给自己定锚", "理由用“第一、第二”编号", "写成文章/口播稿时：观点 P → 原因 R → 例子 E → 总结 P"]','先亮观点，再讲为什么，再举一个真实例子，最后回到观点并升华一层。例子是这个结构的分量所在：有时间、地点、人物三要素才可信；权威案例（名人名企）有说服力，作者亲历最有感染力——亲历只能用个人档案或素材里有的。适合短文、口播、知乎短答，讲不止一个观点时换成金字塔。','C',0);
INSERT INTO "framework" VALUES(2,'pyramid','金字塔原理','结构表达','结论先行、以上统下、归类分组、逻辑递进：想的时候爬金字塔，说的时候溜金字塔。','[{"key": "1", "name": "结论先行", "desc": "第一句话说结论或诉求"}, {"key": "2", "name": "以上统下", "desc": "每个上层观点是下层内容的总结"}, {"key": "3", "name": "归类分组", "desc": "同一层的要点属于同一类，不重不漏"}, {"key": "4", "name": "逻辑递进", "desc": "按时间、结构或重要性排序"}]','汇报工作、写邮件、讲方案、回答复杂问题','结论：这个项目建议延期一周上线。原因分三类——技术上，支付接口联调还差 2 个场景；运营上，活动物料周四才能到；风险上，赶工上线投诉率预计翻倍。所以延期一周、下周四上线最稳。','["从背景讲起，听的人等不到重点", "同一层要点混着不同维度", "细节太早展开，没给对方“气口”"]','["结论一句话能说完，说不完就是没想清楚", "写成文章/口播稿时：结论先行 → 分论点一 → 分论点二 → 分论点三 → 回扣结论"]','结论先行、以上统下、归类分组、逻辑递进。开头一句话给结论；分论点 3 个最好（读者短期记忆就 3-5 项），三个必须是同一个维度（都是原因、都是步骤、或都是方面），并且按时间、重要性或因果排好顺序；每个分论点都要是它下面论据的概括。最容易翻车的地方：分论点之间有重叠，或者一个讲原因一个讲做法，混在一起读者就乱了。','C',1);
INSERT INTO "framework" VALUES(3,'scqa','SCQA 故事化开场','结构表达','背景-冲突-问题-答案，用一个小悬念把听众带进你的方案。','[{"key": "S", "name": "背景 Situation", "desc": "大家都认同的现状"}, {"key": "C", "name": "冲突 Complication", "desc": "现状里出现的变化或麻烦"}, {"key": "Q", "name": "问题 Question", "desc": "于是我们要回答的问题是……"}, {"key": "A", "name": "答案 Answer", "desc": "你的方案/结论"}]','提方案、专题会、演讲开头、写汇报开头','我们一直靠线下门店获客（S），但今年门店客流降了 30%（C）。那怎么把流失的客人找回来（Q）？我的建议是用社群+到店券把老客户先接住（A）。','["冲突不够痛，听众没感觉", "只抛问题不给答案", "背景说太长变成流水账"]','["写成文章/口播稿时：情境 S → 冲突 C → 问题 Q → 答案 A"]','前两步制造张力，第三步把张力收成一个明确的问题，第四步给判断并配论据。冲突要真，不能硬造；答案要给论据，不能只表态。适合讲一个观点、一个判断，不适合讲多件事。','C',2);
INSERT INTO "framework" VALUES(4,'zfz','总分总','结构表达','总起点题，分点展开，总结收尾——最稳的万能结构。','[{"key": "总", "name": "总起", "desc": "一句话点题：今天我介绍三点"}, {"key": "分", "name": "分点", "desc": "数字+关键词+展开"}, {"key": "总", "name": "总结", "desc": "数字+关键词+观点"}]','产品介绍、培训分享、即兴发言、任何不知道怎么组织的话','我们这款课主要有三个特点（总）：一是短，每节 10 分钟；二是实，每节都配练习；三是陪，有老师一对一点评（分）。短、实、陪，就是它适合上班族的原因（总）。','["分点之间没有区分度", "结尾只说“就这些”，没有总结"]','[]','','C',3);
INSERT INTO "framework" VALUES(5,'star','STAR 经历讲述','结构表达','情境-任务-行动-结果，把一段经历讲得具体可信。','[{"key": "S", "name": "情境 Situation", "desc": "当时的背景"}, {"key": "T", "name": "任务 Task", "desc": "你要解决什么"}, {"key": "A", "name": "行动 Action", "desc": "你具体做了什么（重点）"}, {"key": "R", "name": "结果 Result", "desc": "用数字说明结果"}]','面试讲经历、述职、晋升答辩、展示业绩','去年双十一前（S），我负责把活动转化率从 2% 提到 3%（T）。我把落地页拆成 3 版做 AB 测试，并把客服话术重写了一遍（A），最终转化做到 3.4%，多卖了 120 万（R）。','["A 部分说“我们”，听不出你本人做了什么", "R 没有数字", "S 和 T 讲太长"]','["写成文章/口播稿时：情境 S → 任务 T → 行动 A → 结果 R → 可复用的经验"]','情境交代背景和难处，任务说清你要负责的目标和指标，行动是重点——你具体做了什么、对上对下怎么推动、关键的几个决定，结果用数据说话，不能写「优化了」「提升了」这种模糊词。最后加一段「可复用的经验」，让读者能用上。经历和数字只能用作者个人档案里有的，没有的不编。','C',4);
INSERT INTO "framework" VALUES(6,'five_w','五何叙事法','结构表达','何时-何地-何人-何事-何故+总结，像新闻播报一样把事讲清楚。','[{"key": "时", "name": "何时", "desc": "时间由大到小，直奔主题"}, {"key": "地", "name": "何地", "desc": "地点由大到小"}, {"key": "人", "name": "何人", "desc": "事情的主角"}, {"key": "事", "name": "何事", "desc": "过程+细节+结果，用“首先、其次”"}, {"key": "故", "name": "何故", "desc": "原因放后面，制造悬念"}, {"key": "总", "name": "总结", "desc": "一句话提炼升华"}]','讲一件事、复述经过、汇报突发情况','昨天下午三点，在城东门店，一位老客户投诉会员卡余额被清零。我们核查发现是系统升级时漏迁了数据，已经当场补回并送了一次护理。原因是升级前没做数据核对。这件事提醒我们：任何系统变更都要先对账。','["原因一开始就说透，没有悬念", "细节太多没有结论"]','[]','','C',5);
INSERT INTO "framework" VALUES(7,'v_story','V 字成功故事','结构表达','困难-努力-成功，先往下讲难，再往上讲成，情绪有起伏才动人。','[{"key": "↓", "name": "描述困难", "desc": "数据、对比、感受"}, {"key": "→", "name": "描述努力", "desc": "过程中的关键动作"}, {"key": "↑", "name": "描述成功", "desc": "看到的、听到的结果"}]','分享成功经验、获奖感言、团队动员、述职亮点','接手时这个店连续 6 个月亏损，员工走了一半（困难）。我们每天早上开 10 分钟复盘会，把每个老客户都打了一遍电话（努力）。第三个月扭亏，上周还拿了区域第一（成功）。','["困难轻描淡写，成功就不显得难得", "只讲自己，忘了团队"]','[]','','C',6);
INSERT INTO "framework" VALUES(8,'wenyuanfang','问元芳：问题-原因-方案','结构表达','遇到问题时：先说问题，再分析原因，最后给方案。','[{"key": "问", "name": "问题", "desc": "现在出了什么问题"}, {"key": "元", "name": "原因", "desc": "为什么会这样（1-3 个）"}, {"key": "芳", "name": "方案", "desc": "我建议怎么做"}]','被问“怎么办”、复盘会、提改进建议','现在的问题是新客户首单后流失严重（问）。原因主要是首单后没人跟进，也没有复购优惠（元）。我建议首单 3 天内由专人回访，并发一张满减券（芳）。','["只讲问题不给方案，像在抱怨", "原因归咎他人"]','[]','','C',7);
INSERT INTO "framework" VALUES(9,'ganhuilai','感回来：感谢-回顾-愿景','结构表达','感谢在前，回顾细节，展望未来——各种致辞感言的骨架。','[{"key": "感", "name": "感谢", "desc": "具体感谢谁"}, {"key": "回", "name": "回顾", "desc": "一两个有细节的瞬间"}, {"key": "来", "name": "未来", "desc": "对未来的期待和愿景"}]','年会发言、欢送会、感谢致辞、纪念日','首先感谢大家这一年的付出（感）。还记得 6 月那次通宵赶标书，凌晨三点大家还在改 PPT（回）。明年我们要拿下 3 个省的订单，我相信我们做得到（来）。','["感谢太泛，“感谢所有人”", "回顾没有细节"]','[]','','C',8);
INSERT INTO "framework" VALUES(10,'huoqidong','霍启东：收获-启发-行动','结构表达','分享感受时：我收获了什么、得到什么启发、接下来怎么做。','[{"key": "获", "name": "收获", "desc": "具体学到了什么"}, {"key": "启", "name": "启发", "desc": "对我有什么触动"}, {"key": "动", "name": "行动", "desc": "接下来我会怎么做"}]','培训后分享、读书分享、会议总结、被点名谈感受','今天最大的收获是“结论先行”（获）。我发现自己以前汇报总从背景讲起，老板等得着急（启）。从明天的周报开始，我第一句就写结论（动）。','["只说“收获很大”没有具体内容", "没有落到行动"]','[]','','C',9);
INSERT INTO "framework" VALUES(11,'answer3','回答问题公式','结构表达','感谢提问-停顿思考-复述/转换问题-事实+观点+行动。','[{"key": "1", "name": "欢迎态度", "desc": "谢谢您的提问"}, {"key": "2", "name": "思考停顿", "desc": "停 1-2 秒，显得认真"}, {"key": "3", "name": "复述转换", "desc": "把尖锐问题转成中性角度（离职原因→职业规划）"}, {"key": "4", "name": "回答", "desc": "我发现（事实）、我认为（观点）、我承诺（行动）"}]','答记者/领导/观众提问、面试、汇报答疑','谢谢您的问题。（停顿）您问的其实是我们为什么延期——我发现问题出在供应商交付晚了 5 天；我认为我们对单一供应商依赖太重；接下来我会引入第二家备选，周五前给您方案。','["抢答，没听完问题", "复述时语气带情绪", "只解释不给行动"]','[]','','C',10);
INSERT INTO "framework" VALUES(12,'goal3','谈目标：现状-目标-行动','结构表达','讲目标时：为什么（现状）、是什么（2-3 个目标）、怎么做（行动计划）。','[{"key": "为", "name": "现状", "desc": "举例说明现状和差距"}, {"key": "是", "name": "目标", "desc": "2-3 个可衡量的目标"}, {"key": "做", "name": "行动", "desc": "具体的行动计划和节点"}]','年度规划、述职展望、项目启动、动员讲话','上半年我们复购率只有 18%（现状）。下半年目标是复购率 25%、会员数翻倍（目标）。7 月上线会员日，8 月做老带新，每月复盘一次（行动）。','["目标太虚，“更上一层楼”", "没有时间节点"]','[]','','C',11);
INSERT INTO "framework" VALUES(13,'impromptu2','即兴发言 2 步走','即兴与当众','被突然点名时：先稳住争取时间，再总结+补充或认同。','[{"key": "1", "name": "稳住+感谢", "desc": "谢谢领导给机会，我简单说一点想法（为自己争取几秒）"}, {"key": "2", "name": "总结+补充", "desc": "我刚才听下来主要有 3 点……我补充一个/我比较认同其中……"}]','会议上被临时 cue、领导突然问看法','谢谢王总，我简单说一点。刚才大家主要讲了三点：渠道、价格和服务。我比较认同服务这块，我再补充一个一线的感受：客户最在意的是售后响应速度，我们现在平均要 2 天。','["说“我没想好”，浪费表现机会", "一紧张讲太多，跑题", "完全重复别人的话"]','["开会时随手记笔记并归类，被 cue 时就有素材"]','','C',1012);
INSERT INTO "framework" VALUES(14,'impromptu4','即兴演讲 4 大公式','即兴与当众','按场合选一个公式套：讲观点用 PREP，谈问题用问元芳，致谢用感回来，谈感受用霍启东。','[{"key": "P", "name": "PREP", "desc": "观点-理由-案例-观点：被问看法时"}, {"key": "问", "name": "问元芳", "desc": "问题-原因-方案：被问怎么办时"}, {"key": "感", "name": "感回来", "desc": "感谢-回顾-愿景：致辞感言时"}, {"key": "霍", "name": "霍启东", "desc": "收获-启发-行动：分享感受时"}]','任何临时需要开口的场合','被问“下季度怎么提转化率”——用问元芳：现在的问题是……原因是……我的方案是……','["想得太多，迟迟开不了口", "公式套得太生硬，没有自己的例子"]','["即兴表达 80% 靠平时积累：多攒工作中的例子和数据"]','','C',1013);
INSERT INTO "framework" VALUES(15,'host_open','主持开场：称迎重人请','即兴与当众','称呼问好-欢迎点题-强调重要性-塑造主讲人-掌声有请。','[{"key": "称", "name": "称呼问好", "desc": "尊敬的各位领导、各位同事，大家好"}, {"key": "迎", "name": "欢迎点题", "desc": "欢迎来到……我是主持人××"}, {"key": "重", "name": "重要性", "desc": "今天这个主题为什么重要（可用封闭式提问）"}, {"key": "人", "name": "塑造主讲人", "desc": "2-3 个亮点，最好带数字"}, {"key": "请", "name": "有请", "desc": "让我们掌声有请+头衔+全名"}]','主持活动、会议开场、介绍嘉宾','各位同事大家好！欢迎来到季度分享会，我是今天的主持人小李。最近大家是不是都被转化率困扰？今天的嘉宾带团队一个季度把转化提升了 40%，服务过 200 多家门店。让我们掌声有请销售总监——张伟老师！','["主持人讲太多，喧宾夺主", "介绍嘉宾念简历", "有请时名字和头衔说错"]','[]','','C',1014);
INSERT INTO "framework" VALUES(16,'award_speech','获奖感言：谢归用谢','即兴与当众','总体感谢-归功他人-这次获奖的作用-再次感谢。','[{"key": "谢", "name": "总体感谢", "desc": "感谢公司/评委给这个荣誉"}, {"key": "归", "name": "归功", "desc": "归功于团队、领导（含自己的一份）"}, {"key": "用", "name": "作用", "desc": "这个奖对我意味着什么、要怎么用"}, {"key": "谢", "name": "再次感谢", "desc": "收尾再谢一次"}]','年会领奖、表彰发言、颁奖典礼','谢谢公司给我们团队这个奖！这个奖属于每一位加班到深夜的伙伴，特别是小王和老陈。它让我们知道方向是对的，明年我们要把这套打法复制到 3 个新城市。再次谢谢大家！','["只谢自己或只谢领导", "讲成述职报告", "超时"]','[]','','C',1015);
INSERT INTO "framework" VALUES(17,'toast','祝酒词：场意举贺干','即兴与当众','尊称问好点场合-讲意义（过去现在将来）-提议举杯-送祝福-干杯。','[{"key": "场", "name": "场合", "desc": "尊称+问好+今天为什么聚"}, {"key": "意", "name": "意义", "desc": "过去（故事细节）/现在（感受）/将来（愿景）"}, {"key": "举", "name": "提议", "desc": "我提议，大家共同举杯！（停顿）"}, {"key": "贺", "name": "祝贺", "desc": "四字祝福语"}, {"key": "干", "name": "干杯", "desc": "干杯！"}]','饭局开场、客户答谢宴、婚宴、团建','各位领导、各位贵宾，晚上好！今天是我们合作的第三年。还记得第一年为了一个方案，张总陪我们改到凌晨两点。新的一年，希望我们一起把业务做到全国。我提议——大家共同举杯！祝各位身体健康、事业兴旺，干杯！','["讲太长，菜都凉了", "提议举杯前没停顿，大家没反应过来", "祝福语千篇一律"]','[]','','C',1016);
INSERT INTO "framework" VALUES(18,'selfintro_4x','职场自我介绍 4+X','即兴与当众','4 个基本项 + 1-2 个让人记住的特色。','[{"key": "4", "name": "基本项", "desc": "问好、姓名、职业、来自哪里"}, {"key": "X1", "name": "社交特色", "desc": "爱好/金句/称呼——一句话让人记住"}, {"key": "X2", "name": "职业特色", "desc": "过去（成绩用数据）、现在（优势 2-3 点）、未来（能为大家做什么）"}]','入职介绍、会议破冰、商务场合、社群自我介绍','大家好，我是王磊，做了 6 年新媒体运营，来自杭州。大家叫我“磊子”就好，我是个跑步爱好者，跑过 4 个全马。之前我把一个账号从 0 做到 50 万粉丝，接下来很想和大家一起把私域做起来。','["流水账念简历", "过于谦虚没有亮点", "介绍完没有和在场的人建立连接"]','[]','','C',1017);
INSERT INTO "framework" VALUES(19,'speech_open','演讲精彩开头 5 式','即兴与当众','提问式、数据式、故事式、名言式、现挂式，任选其一抓住注意力。','[{"key": "问", "name": "提问式", "desc": "封闭式提问调动互动；开放式提问引发思考"}, {"key": "数", "name": "数据式", "desc": "一个与主题相关、触目惊心的数据"}, {"key": "故", "name": "故事式", "desc": "一个小故事直接进入情境"}, {"key": "名", "name": "名言式", "desc": "一句贴切的名言"}, {"key": "现", "name": "现挂式", "desc": "就地取材，联系现场的人和事"}]','演讲、培训开场、动员讲话','（数据式）大家知道吗？我们 60% 的客户流失，发生在购买后的第一周。','["开场先道歉“我准备得不好”", "开头和主题无关"]','[]','','C',1018);
INSERT INTO "framework" VALUES(20,'speech_end','三段式结尾','即兴与当众','总结-号召行动-升华，结尾决定听众记住什么。','[{"key": "总", "name": "总结", "desc": "综上所述……"}, {"key": "号", "name": "号召", "desc": "我真诚地号召大家……"}, {"key": "升", "name": "升华", "desc": "2-3 个排比句，从个人到团队到更大"}]','演讲收尾、动员讲话、培训结束','今天讲了三件事：结论先行、数据说话、给出方案。我号召大家从明天的周报开始试一试。当每个人都说得清楚，团队就能走得更快，公司就能走得更远！','["草草收尾“就这样吧”", "结尾又展开新内容"]','[]','','C',1019);
INSERT INTO "framework" VALUES(21,'feeling_speech','发表感言：人+细节+情绪+收获','即兴与当众','被点名发表感言时，就地取材讲一个人、一个细节。','[{"key": "人", "name": "人", "desc": "点出一个具体的人"}, {"key": "细", "name": "细节", "desc": "一个有画面的细节"}, {"key": "情", "name": "情绪", "desc": "当时的感受"}, {"key": "获", "name": "收获", "desc": "我收获/想到了什么"}]','活动结束谈感受、欢送会、团建分享','今天最打动我的是保洁阿姨。我七点到的时候，她已经把会场每张椅子都擦过一遍了。那一刻我挺惭愧的——我们总说专业，其实专业就是把小事做到位。','["空喊口号“非常感动”", "感言变成工作汇报"]','[]','','C',1020);
INSERT INTO "framework" VALUES(22,'training_open','培训分享暖场','即兴与当众','破冰-主题-目的-安排-后续跟进，开场 3 分钟让大家进入状态。','[{"key": "1", "name": "破冰", "desc": "一个与大家相关的问题或小互动"}, {"key": "2", "name": "主题", "desc": "今天讲什么"}, {"key": "3", "name": "目的", "desc": "听完能解决什么问题"}, {"key": "4", "name": "安排", "desc": "时间和模块"}, {"key": "5", "name": "跟进", "desc": "结束后的练习/答疑安排"}]','部门培训、内部分享、新人培训','先请大家举手：上周被客户问倒过的有几位？（破冰）今天我们就聊“如何回答客户的刁钻问题”（主题），听完你能拿走 5 个现成话术（目的）。一共 40 分钟，讲 20 分钟、练 15 分钟、答疑 5 分钟（安排）。','["一上来就讲内容，没人进入状态", "不说时长，大家心里没底"]','[]','','C',1021);
INSERT INTO "framework" VALUES(23,'report_progress','进度汇报：结论-节点-风险-下一步','向上沟通','先说整体是否正常，再逐个关键节点，有风险带方案。','[{"key": "1", "name": "整体结论", "desc": "整体进入××阶段，进度正常/有风险"}, {"key": "2", "name": "关键节点", "desc": "逐项：状态+预计完成时间"}, {"key": "3", "name": "风险", "desc": "哪项有延误风险、原因是什么"}, {"key": "4", "name": "下一步", "desc": "我准备怎么做/需要什么支持"}]','周报、日常进度同步、电梯汇报','王总，汇报一下项目进度：整体进入验收阶段，没有延误风险。三个关键点：接口开发已完成；测试有一项潜在风险，因为测试环境周三才能到，我已经协调先用预发环境；上线计划不变，下周五。','["等领导来催才汇报", "只说做了什么，不说状态和风险", "风险不带方案"]','["“凡事有交代，件件有着落，事事有回音”"]','','C',2022);
INSERT INTO "framework" VALUES(24,'report_emergency','突发事件汇报','向上沟通','及时但带着思考：定性-影响-方案 A/B 利弊-我的倾向-请示。','[{"key": "1", "name": "定性", "desc": "刚出现一件比较紧急的事……"}, {"key": "2", "name": "影响", "desc": "可能导致……"}, {"key": "3", "name": "方案", "desc": "方案一好处/弊端；方案二好处/弊端"}, {"key": "4", "name": "倾向", "desc": "我个人倾向方案二，因为……"}, {"key": "5", "name": "请示", "desc": "听听您的意见"}]','出事故、客户投诉升级、项目重大风险','王总，刚出了一个紧急情况：核心供应商通知要延期两周，会影响合同里的上线时间。我想了两个方案：一是换备选供应商，能赶上但成本多 8 万；二是和客户协商延期一周，成本不变但有违约风险。我倾向方案一，您看呢？','["慌慌张张只报问题", "等想清楚所有细节才报，错过时机", "只给一个方案，领导没得选"]','[]','','C',2023);
INSERT INTO "framework" VALUES(25,'research_report','研究结论汇报','向上沟通','约时间-先总结结论-分维度展开-风险与成本收益-听建议。','[{"key": "1", "name": "约时间", "desc": "上次您让我研究××，有初步结论了，约您 30 分钟？"}, {"key": "2", "name": "总结", "desc": "整体来说××比较符合预期，但有××风险"}, {"key": "3", "name": "维度", "desc": "主要看 3 个维度……"}, {"key": "4", "name": "成本收益", "desc": "潜在的成本与收益"}, {"key": "5", "name": "请建议", "desc": "先听您的建议，下一步怎么推进"}]','调研结果、可行性分析、方案对比','上次您让我研究入驻 A 平台，初步结论是值得做，但要控制投入节奏。我从流量、竞争、成本三个维度看了……前三个月预计投入 15 万，回本周期 5 个月。您看哪块需要再细化？','["把研究过程从头讲一遍", "只给结论不给依据"]','[]','','C',2024);
INSERT INTO "framework" VALUES(26,'task_confirm','接任务五确认','向上沟通','老板说不清楚时，用骨架问题帮他说清楚：目标、范围、交付、时间、资源。','[{"key": "目", "name": "目标预期", "desc": "您期望大概是什么样？有参考吗？"}, {"key": "范", "name": "范围", "desc": "只做××部分，××需要包括吗？"}, {"key": "交", "name": "交付形式", "desc": "最后交给您的是一份××对吧？"}, {"key": "时", "name": "截止时间", "desc": "周三给初步、周五第一稿可以吗？"}, {"key": "资", "name": "可协调资源", "desc": "××部分我可以找谁配合？"}]','接到模糊的任务、跨部门需求、客户新需求','好嘞收到！我跟您确认几点：这次是只做华东区的数据吧？最后给您一份 PPT 加一份明细表？周三先给您框架，周五出完整版，可以吗？数据这块我可以直接找财务的小李要吗？','["只回一个“好的”", "追问太细，把老板问烦", "不确认就闷头做，最后返工"]','["执行中遇到分岔路口，再带着两个方向去找老板拍板"]','','C',2025);
INSERT INTO "framework" VALUES(27,'need_formula','提需求万能公式','向上沟通','我的需求是什么 → 我们的共同目标是什么 → 满足我的需求如何帮我们实现共同目标。','[{"key": "1", "name": "深层需求", "desc": "想清楚我真正要什么（认可？收入？资源？）"}, {"key": "2", "name": "共同目标", "desc": "对方要什么、我们共同要什么"}, {"key": "3", "name": "连接", "desc": "满足我的需求，怎样帮我们实现共同目标"}]','要资源、要涨薪、要支持、要调岗','为了下季度把华南的销售额做到 500 万（共同目标），我需要再加一个销售助理（需求）。现在我 40% 的时间花在做报表上，有了助理，我能多跑 20 个客户（连接）。','["抱怨式：“最近太难了”", "暧昧式：“能不能考虑一下……”", "威胁式：“不加人我就……”"]','[]','','C',2026);
INSERT INTO "framework" VALUES(28,'resource_request','申请资源六要素','向上沟通','要资源≠要资源，是要解决问题：紧迫性-现状-工作量-已做的努力-高低两套方案-好消息。','[{"key": "1", "name": "紧迫性", "desc": "业绩、客户、时间节点为什么紧"}, {"key": "2", "name": "现状", "desc": "预算/人手已经压到多低"}, {"key": "3", "name": "工作量", "desc": "接下来还要增加什么"}, {"key": "4", "name": "已做努力", "desc": "我已经做了什么（站在老板这边）"}, {"key": "5", "name": "方案", "desc": "具体方案，准备高低两套"}, {"key": "6", "name": "好消息", "desc": "之前的成绩、接下来的目标"}]','申请人员、预算、资源位','我理解现在现金流紧张，先跟您说下团队的情况：6 月是高峰，客户还要开二期；我们人均收入比市场低 15%，已经走了 2 个；我先用内部调岗顶住了。我想申请 3 万激励预算，最低 2 万也能稳住核心的 3 个人。上季度我们超额 20%，这季度目标是再超 10%。','["没准备直接开口要", "只考虑自己的需求，不考虑老板的优先级", "不算投入产出"]','[]','','C',2027);
INSERT INTO "framework" VALUES(29,'criticism_receive','被批评时的应对','向上沟通','先接住情绪，再一次性把问题问出来，最后用行动形成默契。','[{"key": "1", "name": "接住", "desc": "充分讲出问题的严重性，真诚道歉，不急着解释"}, {"key": "2", "name": "请教", "desc": "借机问：还有哪些地方需要我改进？"}, {"key": "3", "name": "缓冲", "desc": "对方缓和时别瞬间变开心，保留一点认真反思的状态"}, {"key": "4", "name": "默契", "desc": "之后把同类事情做到位，主动反馈已改进"}]','被领导批评、被客户指责','您说得对，这次在客户面前报错数据，不只是我丢面子，是让公司在客户那失了分，后果比我想的严重。我已经重新核对了所有数据。也想借这个机会请教您，最近我还有哪些地方需要改进？','["每一句都跳出来解释，像在辩解", "只受气不解决问题", "被批评后一段时间躲着领导"]','[]','','C',2028);
INSERT INTO "framework" VALUES(30,'extra_work','被安排额外工作时','向上沟通','先承接情绪，盘清现状给方案，再在合适场合提条件。','[{"key": "1", "name": "承接", "desc": "理解这件事重要/棘手，不表现抗拒"}, {"key": "2", "name": "盘点", "desc": "盘清现有工作和新工作的量"}, {"key": "3", "name": "方案", "desc": "给出可行的节奏或请领导定优先级"}, {"key": "4", "name": "条件", "desc": "合适的时机提出需要的支持或发展诉求"}]','临时加活、接手离职同事工作、超出职责的任务','明白，这个项目对咱们挺重要的，现在交接确实棘手。我手上的季度报告周一要交，我建议报告按原计划，竞品分析我先做框架周三给您，完整版下周五，您看可以吗？','["马上拒绝", "开口就谈条件涨薪", "什么都揽下来最后都做不好"]','[]','','C',2029);
INSERT INTO "framework" VALUES(31,'leave_request','请假沟通','向上沟通','私下请、讲清工作安排，让老板有理由批。','[{"key": "1", "name": "私下", "desc": "永远私下请假"}, {"key": "2", "name": "理解", "desc": "我知道最近正是关键期，××马上要交付"}, {"key": "3", "name": "安排", "desc": "哪些提前做完、哪些找谁顶、什么时候交"}, {"key": "4", "name": "承诺", "desc": "每天/每周同步进度，保证不耽误"}]','请假、调休、请长假','王总，我可能要跟您请两天假，家里有点事。我知道这周方案要交，我今晚把初稿做完发您，修改部分小陈可以帮我盯，周四回来我第一时间对齐。','["理由讲太多太细", "当着大家面请假", "只说请假不说工作怎么办"]','[]','','C',2030);
INSERT INTO "framework" VALUES(32,'resign','提离职','向上沟通','真诚、讲职业规划、表达感谢、谈好交接，好聚好散。','[{"key": "1", "name": "决定", "desc": "坦诚而坚定地说出决定"}, {"key": "2", "name": "理由", "desc": "从职业规划讲，不比较好坏"}, {"key": "3", "name": "感谢", "desc": "回顾正向的合作和收获"}, {"key": "4", "name": "交接", "desc": "主动提出交接方案和时间"}]','提离职、被挽留','何总，我想跟您说一个决定，我准备离职了。这几年在您手下学到最多的是做决策的方法。我想去试一试从 0 到 1 做业务，这是我一直想走的路。交接这块我准备了清单，一个月内交接完，您看可以吗？','["吐槽公司或领导", "透露下家具体信息", "被挽留时当场答应又反悔"]','[]','','C',2031);
INSERT INTO "framework" VALUES(33,'criticize_formula','批评下属六步','团队管理','对事不对人：主题-了解全貌-问题与影响-建议赋能-征询意见-成效约定。','[{"key": "1", "name": "主题", "desc": "不寒暄，直接点明这次要谈的事"}, {"key": "2", "name": "全貌", "desc": "你觉得主要是什么造成的？先听对方说经过"}, {"key": "3", "name": "影响", "desc": "总结原因，讲清对工作/团队/个人的影响"}, {"key": "4", "name": "建议", "desc": "给出可行建议，并问有什么困难"}, {"key": "5", "name": "征询", "desc": "那我们按这个来，你看可以吗？"}, {"key": "6", "name": "约定", "desc": "一个月后再碰一下看效果"}]','下属工作失误、延期交付、屡教不改','今天约你是聊上周交付延期的事，客户那边扣了 5% 的款。你觉得主要是什么原因？……我总结一下，主要是排期没留缓冲、风险没及时报。下个项目每周五给我同步一次风险，你觉得有什么困难吗？一个月后我们再复盘一次。','["想批评就批评，没有标准", "不分场合，当众批评", "七分肯定三分否定，批评没效果", "人身攻击"]','["扬善于公堂，归过于密室"]','','C',3032);
INSERT INTO "framework" VALUES(34,'persuade_sub','说服下属接受调整','团队管理','讲背景-接情绪-说选你的理由-讲长期价值-听意见-坐实-跟进。','[{"key": "1", "name": "背景", "desc": "业务/人员上为什么要调整"}, {"key": "2", "name": "共情", "desc": "我知道比较突然……"}, {"key": "3", "name": "理由", "desc": "为什么选你（你的优势）"}, {"key": "4", "name": "价值", "desc": "职业规划、成长的短中长期分析"}, {"key": "5", "name": "征询", "desc": "你怎么看？（别问“你有什么顾虑”）"}, {"key": "6", "name": "坐实", "desc": "那就定了，今天我拉个群"}, {"key": "7", "name": "跟进", "desc": "第一天/周/月持续跟进"}]','调岗、加任务、接新业务','下季度我们要开线上业务，我想请你来牵头。我知道你一直做线下，这个调整挺突然。选你是因为你最懂我们的客户，线上线下都会的人，未来路会宽很多。你怎么看？不用马上回我，这周内给我答复就行。','["用领导身份强压", "被对方的顾虑反说服", "调整后不管不问"]','[]','','C',3033);
INSERT INTO "framework" VALUES(35,'feedback3','三种有效反馈','团队管理','事实式、求助式、关怀式——用合作思维代替权力思维。','[{"key": "事", "name": "事实式", "desc": "放下评判，用事实说话：这周有三次迟到超过 15 分钟"}, {"key": "求", "name": "求助式", "desc": "进度落后 3 天了，我们一起看看怎么办？"}, {"key": "关", "name": "关怀式", "desc": "你业绩连续 3 个月下滑，还好吗？是有什么困难吗？"}]','日常管理、一对一沟通、绩效面谈','这个月你有两次周报晚交（事实）。我想听听是不是遇到什么困难了？（关怀）我们一起看看有没有办法让你省点时间（求助）。','["“你为什么总是……”带评判", "只说问题不给支持"]','[]','','C',3034);
INSERT INTO "framework" VALUES(36,'sandwich','三明治点评（优势加强法）','团队管理','具体赞美 + 提升建议 + 总体鼓励，用“如果……就更好了”代替“但是”。','[{"key": "1", "name": "具体赞美", "desc": "说出具体好在哪里"}, {"key": "2", "name": "提升建议", "desc": "如果××，就更好了"}, {"key": "3", "name": "总体鼓励", "desc": "整体肯定和期待"}]','点评下属、点评同事的发言/方案、带新人','这份方案数据做得很扎实，尤其是竞品对比那页一目了然。如果开头先放结论，领导会看得更快。整体非常好，我觉得可以直接拿去给客户讲了。','["夸得太空“挺好的”", "用“但是”转折，前面的夸都白夸了"]','[]','','C',3035);
INSERT INTO "framework" VALUES(37,'motivate','激励下属：看见-需求-陪伴','团队管理','认同、关注、为对方做点什么，比空洞打气有效。','[{"key": "1", "name": "看见", "desc": "具体说出对方的付出"}, {"key": "2", "name": "需求", "desc": "了解对方真正想要什么（成长/认可/稳定）"}, {"key": "3", "name": "目标", "desc": "把困难变成一起攻克的目标"}, {"key": "4", "name": "支持", "desc": "我能为你做什么"}]','下属情绪低落、团队受挫、懈怠期','这三个月大家每天都加班，我都看在眼里。这次没中标，不是因为大家不够努力。我们一起复盘一下差在哪里，下个月的投标我陪大家一起改方案。','["只会批评不会表扬", "画饼不落地", "激励一部分人时打击了另一部分人"]','[]','','C',3036);
INSERT INTO "framework" VALUES(38,'task_delegate','布置任务讲清四要素','团队管理','背景目标、交付标准、截止时间、资源与求助人，最后确认对方复述。','[{"key": "1", "name": "背景目标", "desc": "为什么做、做成什么样"}, {"key": "2", "name": "标准", "desc": "做到什么程度算完成"}, {"key": "3", "name": "时间", "desc": "什么时候交初稿、终稿"}, {"key": "4", "name": "资源", "desc": "可以找谁、用什么"}, {"key": "5", "name": "复述", "desc": "你复述一下我们的约定？"}]','给新人布置任务、委派工作','这次请你整理 30 份用户访谈，目的是找出大家最不满意的三件事。交付一份 Excel，每条标出问题类型。周三先给我前 10 份看方向，周五交完。不懂的可以随时问我或者问小张。你复述一下？','["只说“你弄一下”", "没有标准，交上来再返工", "不确认对方是否听懂"]','[]','','通用',3037);
INSERT INTO "framework" VALUES(39,'nvc','非暴力沟通四步','情绪与关系','事实-感受-需要-请求，不指责也能把不满说清楚。','[{"key": "事", "name": "陈述事实", "desc": "只讲客观事实，不加评判"}, {"key": "感", "name": "表达感受", "desc": "我感到失落/着急/担心"}, {"key": "需", "name": "说出需要", "desc": "因为我希望……"}, {"key": "请", "name": "提出请求", "desc": "具体、可执行的请求"}]','提意见、表达不满、亲密关系沟通、反馈问题','这周你有五天都是十一点后才回家（事实），我挺失落的（感受），因为我希望家里能有一起吃饭的时间（需要）。以后每周能有三天八点前回来吗？（请求）','["把评判当事实：“你从来不顾家”", "感受变指责：“我觉得你很自私”", "请求太模糊：“你能不能上点心”"]','[]','','C',4038);
INSERT INTO "framework" VALUES(40,'emotion_down','情绪降级四步','情绪与关系','接纳情绪-鼓励分享-表达理解-共同策划：先处理心情，再处理事情。','[{"key": "1", "name": "接纳情绪", "desc": "听起来你今天特别委屈……"}, {"key": "2", "name": "鼓励分享", "desc": "说说发生了什么？"}, {"key": "3", "name": "表达理解", "desc": "我明白，换我也会生气"}, {"key": "4", "name": "共同策划", "desc": "有什么需要我帮忙的吗？"}]','伴侣/家人抱怨、客户发火、同事情绪激动','听起来你今天真的被气坏了（接纳）。他具体是怎么说的？（分享）……换我也受不了，明明不了解情况还当众批评（理解）。你想怎么处理？要不要我帮你一起想想怎么跟他说？（策划）','["一上来讲道理“职场都这样”", "帮对方的“敌人”说话", "急着给解决方案"]','[]','','C',4039);
INSERT INTO "framework" VALUES(41,'listen_read_say','三站式沟通：听-读-说','情绪与关系','先听情境氛围（对方是支持/开放/防御/对抗），再读需求（原因+意图），最后说。','[{"key": "听", "name": "听情境", "desc": "对方现在是支持、开放、防御还是对抗？"}, {"key": "读", "name": "读需求", "desc": "TA 为什么这么说？TA 期待什么结果？"}, {"key": "说", "name": "说观感", "desc": "以“我理解你”为中心表达自己"}]','冲突沟通、谈判前判断、合作沟通','（发现对方处于防御状态）我能感觉到你对这次调整有些担心（听）。你是担心工作量变大，还是担心做不好？（读）我理解，换成我也会担心，我们先把你最担心的那件事解决掉（说）。','["对方在对抗状态时硬讲道理", "只听字面意思，没读出背后需求"]','["无开放，不沟通"]','','C',4040);
INSERT INTO "framework" VALUES(42,'apology','有效道歉','情绪与关系','说中对方真正的情绪点，承担责任，给补救和承诺。不说“别生气”。','[{"key": "1", "name": "说中情绪", "desc": "说出对方真正在意的点（不是表面的事）"}, {"key": "2", "name": "承担", "desc": "不找借口，不推给别人"}, {"key": "3", "name": "补救", "desc": "我已经/马上做什么"}, {"key": "4", "name": "承诺", "desc": "以后怎么保证不再发生"}]','做错事、让人失望、客户投诉','对不起，这次让你在朋友面前没面子，是我没顾及你的感受（说中）。这是我的问题，不是你小题大做（承担）。我已经跟他们解释清楚了（补救），以后我们出门前我先跟你商量好（承诺）。','["“别生气了”——等于让对方闭嘴", "“对不起，但是……”", "把错推给实习生/别人"]','[]','','C',4041);
INSERT INTO "framework" VALUES(43,'thanks_value','价值感谢','情绪与关系','感谢不只说谢谢，要谢在价值点上：时间、金钱、行为、经验。','[{"key": "1", "name": "做了什么", "desc": "说出对方具体做了什么"}, {"key": "2", "name": "价值", "desc": "这件事帮我节省了时间/钱/少走了弯路"}, {"key": "3", "name": "感受", "desc": "我现在的心情"}, {"key": "4", "name": "回报", "desc": "下次有需要随时开口"}]','感谢帮忙、感谢父母伴侣、感谢领导前辈','今天多亏你帮忙救场（做了什么），不然这个项目可能就黄了（价值）。我真的松了一口气（感受）。下次你有需要，随时找我（回报）。','["只说“谢谢”“辛苦了”", "感谢变客套"]','[]','','A',4042);
INSERT INTO "framework" VALUES(44,'empathy3','三类情绪的共情','情绪与关系','对方开心时放大、尴尬时给台阶、低落时合理化+引导+解决。','[{"key": "正", "name": "正面情绪", "desc": "表达关注+正向强化+归因于对方的努力"}, {"key": "尬", "name": "尴尬窘迫", "desc": "给台阶：我上次也这样；或假装没看见"}, {"key": "负", "name": "负面情绪", "desc": "合理化情绪→向正向引导→一起解决"}]','朋友分享好消息、同事出糗、对方情绪低落','（好消息）这也太棒了吧！不枉你最近那么拼！（尴尬）没事没事，我上次开会也把老板名字叫错了。（低落）有这种情绪很正常，你已经比大多数人做得好了，我们想想办法。','["对方开心时泼冷水", "对方尴尬时追问", "对方难过时说“这有什么”"]','[]','','A',4043);
INSERT INTO "framework" VALUES(45,'gentle','温柔法则','情绪与关系','称呼昵称、命令变商定、要求变请求、严格带温度、批评带关爱。','[{"key": "1", "name": "称呼昵称", "desc": "用亲切的称呼开头"}, {"key": "2", "name": "命令→商定", "desc": "让我们一起……好不好？"}, {"key": "3", "name": "要求→请求", "desc": "可以帮我……吗？"}, {"key": "4", "name": "严格+温度", "desc": "规则不变，语气温和"}, {"key": "5", "name": "批评+关爱", "desc": "我很爱你，但我不能接受这个行为"}]','和孩子、伴侣、长辈沟通；需要说“不”又不想伤感情','宝贝，妈妈看到你有点难过，难过是可以的，妈妈陪着你。我们一起去找找原因好不好？','["温柔变纵容，底线没了", "语气温和但内容在指责"]','["只要和颜悦色，一切皆可谈判"]','','A',4044);
INSERT INTO "framework" VALUES(46,'key_dialog','关键对话三步','情绪与关系','陈述事实-表达想法（对比说明）-征询观点，同时盯住内容和氛围。','[{"key": "1", "name": "陈述事实", "desc": "用客观事实开场，不容易激怒对方"}, {"key": "2", "name": "表达想法", "desc": "我不是……，我是希望……（对比说明）"}, {"key": "3", "name": "征询观点", "desc": "我想听听您的看法"}]','谈加薪、谈分手/矛盾、和长辈谈重大决定','我入职三年，负责了 4 个重点项目，去年业绩超额 30%（事实）。我今天来不是对现在的待遇不满，而是希望我的回报能和贡献更匹配（对比说明）。我想听听您对我工作的看法（征询）。','["上来就摊牌要结果", "气氛不对还继续推进", "忘了谈话目的，突然发火"]','[]','','C',4045);
INSERT INTO "framework" VALUES(47,'disc','DISC 看人说话','情绪与关系','先判断对方的性格色彩，再调整说法：D 要结果、I 要认可、S 要安全、C 要依据。','[{"key": "D", "name": "支配型（黄）", "desc": "直截了当、列举事实、展示效率，别绕弯"}, {"key": "I", "name": "影响型（红）", "desc": "给予赞美、回应认可、培养感情"}, {"key": "S", "name": "稳健型（绿）", "desc": "营造和谐氛围、展示真诚、不催不逼"}, {"key": "C", "name": "谨慎型（蓝）", "desc": "专业深度、数据充分、就事论事"}]','和领导、客户、伴侣沟通前判断对方风格','对 D 型老板汇报：先说结果“这个月超额 20%”；对 C 型老板汇报：先给数据表，再讲逻辑。','["用自己的风格对待所有人", "给人贴标签就不再观察"]','["夸 D 限定范围加“最”；夸 I 随便夸；夸 S 表达感谢；夸 C 夸细节"]','','A',4046);
INSERT INTO "framework" VALUES(48,'topic_fire','点燃话题：同复延问','社交破冰','同频感受-重复要点-延展观点-好奇提问，让对话一直接得住。','[{"key": "同", "name": "同频", "desc": "好巧/对啊，我也……"}, {"key": "复", "name": "复述", "desc": "重复对方的关键词"}, {"key": "延", "name": "延展", "desc": "补充一点自己的观点或经历"}, {"key": "问", "name": "提问", "desc": "用开放式问题把话递回去"}]','和陌生人搭话、饭局破冰、相亲、社交活动','——在看电影呢。——好巧（同），我周末也看了一部电影（复）。你看的哪部？我最近特别迷悬疑片（延），你喜欢什么类型的？（问）','["封闭式提问“你喜欢电影吗”，一句就聊死", "只说自己的事", "查户口式连环问"]','["话题三方向：平行（换同类话题）、放大（往大了聊）、深入（往细了聊）"]','','C',5047);
INSERT INTO "framework" VALUES(49,'praise_spot','聚光灯赞美：事感意连','社交破冰','描述事实-表达感受-看见意义-创造连接，夸到具体才真诚。','[{"key": "事", "name": "事实", "desc": "我看到你……（具体的行为/细节）"}, {"key": "感", "name": "感受", "desc": "让我觉得……"}, {"key": "意", "name": "意义", "desc": "这说明你……（动机、品质）"}, {"key": "连", "name": "连接", "desc": "以后能不能请教你……"}]','认识新朋友、夸领导同事、建立关系','林老师，您刚才讲用户访谈那段，用一张便利贴就把问题归类了（事），我当场就想拿回去用（感）。看得出您是真的在一线做过很多次（意）。以后做访谈能不能请教您几个问题？（连）','["只用形容词“讲得真好”", "夸得太夸张显得假", "夸完就没下文"]','["赞美视角：外在细节、关联信息（籍贯/工作）、行为经历"]','','C',5048);
INSERT INTO "framework" VALUES(50,'help_ask','开口求助','社交破冰','说清需求和理由，帮对方降低成本和风险，再准备一个退一步的方案。','[{"key": "1", "name": "说清需求", "desc": "我是谁、遇到什么情况、需要你帮什么"}, {"key": "2", "name": "为什么找你", "desc": "给出找对方的理由（架起对方）"}, {"key": "3", "name": "降低成本", "desc": "整理好材料，预估“大概占用你半小时”"}, {"key": "4", "name": "降低风险", "desc": "你完全没有责任，我已经很感谢"}, {"key": "5", "name": "备选", "desc": "被拒后提一个更小的请求"}]','请人帮忙、找内推、借东西、找前辈请教','张姐您好，我是市场部小王。下周三我家里有急事得请假，正好轮到我值班。知道您那天也有安排，所以想问能不能换班——我周六替您值一天。实在不方便也没关系，我再问问别人。','["过于委婉，对方不知道要帮什么", "“帮我就请你吃饭”", "被拒绝就放弃"]','[]','','C',5049);
INSERT INTO "framework" VALUES(51,'refer','引荐他人：1 个特点 + 2 个事例','社交破冰','介绍别人时，给一个记忆点再加两个小事例。','[{"key": "1", "name": "特点", "desc": "一个让人记住的标签"}, {"key": "2", "name": "事例", "desc": "2-3 个证明这个标签的小事"}]','介绍朋友认识、会上介绍同事、引荐资源','给您介绍一下小陈，他是我见过最会讲故事的产品经理——去年他一个 5 分钟的演示就拿下了客户 200 万的单子，我们内部培训也是请他讲的。','["只报名字职位", "夸得太满让被介绍的人尴尬"]','[]','','C',5050);
INSERT INTO "framework" VALUES(52,'humor','幽默：铺垫+包袱','社交破冰','先铺垫让人产生预期，再用意外的反转抖包袱；自黑最安全。','[{"key": "铺", "name": "铺垫", "desc": "建立一个正常的预期"}, {"key": "包", "name": "包袱", "desc": "出人意料的反转"}, {"key": "黑", "name": "自黑", "desc": "拿自己开涮，不伤人"}]','活跃氛围、化解尴尬、演讲开场','我减肥很有毅力，坚持了整整三年（铺垫）——每天都在坚持明天开始（包袱）。','["拿别人的短处开玩笑", "玩笑开过界", "一直讲段子显得不专业"]','[]','','C',5051);
INSERT INTO "framework" VALUES(53,'boundary','被冒犯时：幽默+边界+转移','社交破冰','不卑不亢：先用幽默或平静接住，再清楚表达边界，最后转移话题。','[{"key": "1", "name": "接住", "desc": "幽默化解或平静回应，不当场翻脸"}, {"key": "2", "name": "边界", "desc": "清楚地表达“这个话题我不太想聊”"}, {"key": "3", "name": "转移", "desc": "把话题引到别处或反问对方"}]','被当众调侃、被问隐私、被阴阳怪气','哈哈，买厕所还差点，不过够买张去你家吃饭的高铁票（接住）。收入这个话题咱就不聊了啊（边界）。对了，你家孩子今年上几年级了？（转移）','["当场翻脸，场面难收", "忍气吞声，下次变本加厉", "反唇相讥伤了和气"]','[]','','A',5052);
INSERT INTO "framework" VALUES(54,'ask_first','先问后报：问痛点-说重点-答保障','说服与谈判','谁先开口谁被动：先问需求，再讲价值，最后给保障。','[{"key": "问", "name": "问痛点", "desc": "您最关心的是什么？现在最头疼的是什么？"}, {"key": "说", "name": "说重点", "desc": "只讲和痛点相关的价值（性价比）"}, {"key": "答", "name": "答保障", "desc": "如果有风险，我来承担（包退/包赔/试用）"}]','销售、被问“多少钱”、谈合作','张总，报价之前我想先了解一下，您这次最看重的是交期还是价格？……明白，交期的话我们能做到 7 天，比行业快一倍；如果第一批延期，我们按天赔付。','["一上来就报价", "讲一堆和对方无关的卖点", "不敢给保障"]','[]','','D',6053);
INSERT INTO "framework" VALUES(55,'high_low','报价高开低走','说服与谈判','先定底线、期望和报价三个数，报价高开留余地，让步越来越小。','[{"key": "底", "name": "底线目标", "desc": "最低能接受的，心里不慌"}, {"key": "期", "name": "期望目标", "desc": "真正想要的，藏起来"}, {"key": "报", "name": "报价目标", "desc": "“高开”的价格，离谱但可信"}, {"key": "让", "name": "让步节奏", "desc": "越让越小，每次都很为难"}]','谈价格、谈薪资、谈预算','（心里：底线 5%、期望 8%、开口 15%）王经理，考虑到原料今年涨了 25%，我们的调价方案是 15%。……这样，看在合作三年的份上，我回去申请一下 10%。','["先开口报出底线", "一次让到底", "让步太快，对方觉得还有空间"]','[]','','D',6054);
INSERT INTO "framework" VALUES(56,'trade','有条件让步','说服与谈判','让步可以，但必须交换：最后让、越让越小、“请示领导”、一定附带条件。','[{"key": "1", "name": "最后让", "desc": "让步放在最后关头"}, {"key": "2", "name": "请示", "desc": "这超出我的权限，我请示一下领导"}, {"key": "3", "name": "交换", "desc": "如果您能××（加量/预付/长约），我们可以……"}, {"key": "4", "name": "越让越小", "desc": "让步幅度递减，表现得很为难"}]','谈判僵持、对方压价、条件拉锯','600 这个价我真没卖过……我请示了领导，领导说除非签两年合同、预付半年，才能给到这个价。您看可以吗？','["对方一压价就直接答应", "无条件让步", "让步越来越大"]','[]','','D',6055);
INSERT INTO "framework" VALUES(57,'three_cards','谈判三张牌：时间-空间-角度','说服与谈判','僵持时换牌：换时间（拖或急）、换空间（加量/换方案）、换角度（请示领导/换人谈）。','[{"key": "时", "name": "时间牌", "desc": "压缩或拉长时间：今天能定就给您这个价"}, {"key": "空", "name": "空间牌", "desc": "数量多少、范围大小：批量采购/拆分方案"}, {"key": "角", "name": "角度牌", "desc": "权限大小：请示领导、红白脸"}]','谈判僵持、对方不让步','这个价格确实超出我的权限（角度）。如果您这周能确认订单（时间），并且把明年上半年的量一起定下来（空间），我去帮您争取一下。','["只在价格上来回拉锯", "把自己的底牌一次亮光"]','[]','','D',6056);
INSERT INTO "framework" VALUES(58,'goal_guide','目标引导：目现方行','说服与谈判','对方期待的目标-原方案的劣势-新方案的优势-一小步行动，“我们一起赢”。','[{"key": "目", "name": "目标", "desc": "对方期待的结果是什么"}, {"key": "现", "name": "现状", "desc": "原方案的劣势和风险"}, {"key": "方", "name": "方案", "desc": "新方案的优势，补足盲区"}, {"key": "行", "name": "行动", "desc": "对方可以接受的一小步"}]','说服客户/领导/合作方换方案','您的目标是年底前把门店做到 20 家（目）。现在全靠自己开店，资金压力很大（现）。如果用加盟+直营结合，速度能快一倍（方）。要不先拿两家店试点三个月？（行）','["一上来否定对方的方案", "要求对方一步到位"]','[]','','C',6057);
INSERT INTO "framework" VALUES(59,'proposal','提案说服','说服与谈判','重申共同目标-给出专业论证-多方案对比-请对方决策，分歧先定结构再谈细节。','[{"key": "1", "name": "重申目标", "desc": "回到之前达成一致的目标和原则"}, {"key": "2", "name": "专业论证", "desc": "数据、案例、细节，交付完整"}, {"key": "3", "name": "方案对比", "desc": "2-3 个方案的利弊和建议"}, {"key": "4", "name": "请决策", "desc": "我们建议方案 B，您看呢？"}]','向甲方提案、向领导提方案、处理客户反复改需求','我们之前定的目标是三个月清掉临期库存。基于这个目标我们做了两套方案：A 折扣清仓，快但伤品牌；B 做组合礼盒，慢两周但毛利高 12%。我们建议 B，您看呢？','["直接扔结果，没有背景和依据", "客户说不喜欢就全推翻", "方案太多，自己都没把握"]','[]','','C',6058);
INSERT INTO "framework" VALUES(60,'sales3','销售三步：信任-需求-价值','说服与谈判','先卖人、再卖事、再成交：建立信任、挖掘需求、塑造价值并算账。','[{"key": "1", "name": "建立信任", "desc": "处理心情：赞美、给干货、先给予"}, {"key": "2", "name": "挖掘需求", "desc": "5W2H 问出痛点和预算"}, {"key": "3", "name": "塑造价值", "desc": "差异化 + 一句话算账（收益放大、价格缩小）"}, {"key": "4", "name": "保障成交", "desc": "试用、退款、风险承担"}]','推销产品、介绍服务、谈合作','这套系统一年 3 万，听起来不便宜。但您现在 3 个人做报表，一个月人力成本就 4 万，用系统后 1 个人就够了——算下来一个月就回本。','["上来就推产品", "只讲功能不讲对方的收益", "不敢谈价格"]','[]','','D',6059);
INSERT INTO "framework" VALUES(61,'collect_debt','催款：情-理-法-节奏','说服与谈判','先维护关系，再讲合同事实，给出具体时间节点，必要时有后手。','[{"key": "情", "name": "情", "desc": "肯定合作关系，理解对方难处"}, {"key": "理", "name": "理", "desc": "讲清合同约定和已逾期的事实"}, {"key": "时", "name": "时间", "desc": "要一个具体的付款时间/分期方案"}, {"key": "后", "name": "后手", "desc": "必要时说明公司流程（虚拟恶人）"}]','催回款、催尾款、催报销','钱总，咱们合作这么多年，你们最近的难处我也理解。不过这 80 万已经逾期三个月了，财务每周都在问我。您看能不能这个月先付一半，剩下的下月底前结清？不然到季度末，公司流程会自动转法务，我也不好办了。','["一上来就撕破脸", "不好意思开口，一拖再拖", "只说“尽快”，没有具体时间"]','[]','','D',6060);
INSERT INTO "framework" VALUES(62,'interview_intro','面试自我介绍','求职面试','整合亮点而不是念简历：我是谁-做成过什么-为什么适合这个岗位。','[{"key": "1", "name": "我是谁", "desc": "姓名、年限、方向，一句话"}, {"key": "2", "name": "亮点", "desc": "2-3 个做成的事，带数字"}, {"key": "3", "name": "匹配", "desc": "这些经历和岗位要求怎么对应"}, {"key": "4", "name": "引导", "desc": "留一个钩子，引导面试官问你擅长的"}]','面试开场、校招、内部竞聘','我叫李明，做了 5 年产品经理。最有代表性的是从 0 到 1 做了一款会员小程序，半年用户 30 万。我看咱们岗位很重视增长，这正是我过去两年主要在做的事，其中有一次失败的拉新实验，我从中总结了不少方法。','["流水账念简历", "过于简洁没有亮点", "自嗨讲了一堆和岗位无关的"]','[]','','C',7061);
INSERT INTO "framework" VALUES(63,'weakness','优劣势回答','求职面试','优势：多维度+展开一个；劣势：真诚说一个，并讲识别-原因-改进-现状。','[{"key": "识", "name": "我识别到", "desc": "真诚说出一个真实的不足"}, {"key": "因", "name": "为什么", "desc": "这个不足是怎么来的"}, {"key": "改", "name": "如何改", "desc": "我采取了什么行动"}, {"key": "现", "name": "现在怎么样", "desc": "目前改进的效果"}]','被问优缺点、被问不足','我的不足是不太会放权。去年刚带团队时，很多事我都自己做，结果团队成长慢、我也很累。后来我每周把一个任务完整交给组员，只做检查。现在组里两个同事已经能独立负责项目了。','["说一个其实是优点的缺点“我太追求完美”", "自杀式缺点“我经常拖延”", "只说缺点不说改进"]','[]','','C',7062);
INSERT INTO "framework" VALUES(64,'achievement','业绩展示','求职面试','先立标准再给数据，过程业绩、结果业绩、衍生业绩都可以讲。','[{"key": "1", "name": "立标准", "desc": "行业/公司平均是多少"}, {"key": "2", "name": "给数据", "desc": "我做到了多少"}, {"key": "3", "name": "讲做法", "desc": "关键动作 1-2 个"}, {"key": "4", "name": "备追问", "desc": "说一步想三步，细节经得起问"}]','面试、述职、晋升答辩','我们行业门店的平均会员转化率大概 15%，我负责的门店做到了 28%。主要做了两件事：把会员权益从打折改成专属服务；给每个店员设了转化排行榜。','["只说数字没有参照", "说得太飘被问出漏洞", "过度谦虚把功劳都给团队"]','[]','','C',7063);
INSERT INTO "framework" VALUES(65,'gap_explain','敏感问题闭环回答','求职面试','空窗期、离职原因、婚育：淡定-简短说明-填充价值-闭环并转话题。','[{"key": "1", "name": "淡定", "desc": "自信、不心虚"}, {"key": "2", "name": "简短说明", "desc": "讲框架不讲故事"}, {"key": "3", "name": "填充价值", "desc": "这段时间我做了/想清楚了什么"}, {"key": "4", "name": "闭环", "desc": "所以现在……，正好也是我选择咱们公司的原因"}]','空窗期、频繁跳槽、离职原因、婚育问题','这 8 个月我和两个前同事做了个小工作室，接了 6 个品牌的内容订单。做下来发现我更喜欢在成熟团队里把一件事做深，这也是我来面试咱们公司的原因。','["吐槽前公司或前老板", "讲成一个长故事", "撒谎（背调能查出来）"]','[]','','C',7064);
INSERT INTO "framework" VALUES(66,'unknown_q','不会回答的问题','求职面试','不说“不知道”：争取思考时间-给框架-补部分细节-会后补救。','[{"key": "1", "name": "争取时间", "desc": "这个问题我之前没专门准备过，我先说说初步想法"}, {"key": "2", "name": "给框架", "desc": "一般来说这件事包括几个部分……"}, {"key": "3", "name": "补细节", "desc": "结合我的经验，其中××我会……"}, {"key": "4", "name": "补救", "desc": "面试后可以发邮件补充"}]','面试被问倒、汇报被问到没准备的问题','嗯，我先说说初步想法。品牌搭建一般包括内部梳理品牌价值和外部曝光两块。结合我的经验，咱们现阶段我会先做内部梳理，因为……','["直接说“我不知道”", "硬编答案被追问出漏洞", "慌张沉默太久"]','[]','','C',7065);
INSERT INTO "framework" VALUES(67,'salary_talk','谈薪：不先亮牌、讲价值、谈整体','求职面试','先让对方确认要你，再谈数字；用价值和行情支撑；谈不动就谈整体回报。','[{"key": "1", "name": "后报价", "desc": "先了解预算范围：咱们这个岗位的薪资区间是？"}, {"key": "2", "name": "给区间", "desc": "结合行情和我的经验，期望在××到××"}, {"key": "3", "name": "讲价值", "desc": "我能带来××，参考××"}, {"key": "4", "name": "谈整体", "desc": "底薪谈不动就谈签字费、期权、调薪周期"}]','谈 offer、谈加薪、谈晋升','我更关心这个岗位能做的事情。方便先说一下咱们的预算区间吗？……结合市场行情和我做增长的经验，我的期望是 20-22k。如果底薪有压力，我们也可以看看试用期后的调薪安排。','["一上来先报底价", "只说“看着给”", "拿别的 offer 威胁"]','[]','','C',7066);
INSERT INTO "framework" VALUES(68,'ask_back','反问面试官','求职面试','不问结果和工资，问期待、团队和考核，或者补充一个自己的亮点。','[{"key": "1", "name": "补充", "desc": "补充一个刚才没讲到的亮点"}, {"key": "2", "name": "期待", "desc": "如果我入职，您对我前三个月有什么期待？"}, {"key": "3", "name": "团队", "desc": "这个岗位在哪个团队、汇报给谁？"}, {"key": "4", "name": "考核", "desc": "主要的考核维度是什么？"}]','面试结尾“你还有什么问题吗”','我额外补充一点，刚才说到数据分析，其实我自己写过一个自动化报表工具。另外想了解一下，如果我入职，您对我前三个月最大的期待是什么？','["“我通过了吗？”", "上来就问工资福利", "问题超过 3 个"]','[]','','C',7067);
INSERT INTO "framework" VALUES(69,'pain_solution','痛点 → 方案','自媒体创作','先戳中一个具体问题，再给能照做的解决办法。干货、教程类最稳的写法。','[{"key": "1", "name": "痛点场景", "desc": "用一个读者一看就认出来的具体场景开头，不要泛泛地说「很多人都有这个烦恼」（约15%）"}, {"key": "2", "name": "原因拆解", "desc": "说清楚问题为什么会发生，一到三个原因，每个一句话讲透（约20%）"}, {"key": "3", "name": "解决办法", "desc": "分步骤给出能照做的方法，每步写清怎么做、做到什么程度（约40%）"}, {"key": "4", "name": "案例或效果", "desc": "用作者的真实经历或素材证明方法有效；没有素材就写可感的效果，不编数字（约15%）"}, {"key": "5", "name": "行动号召", "desc": "给一个今天就能开始的最小动作，再引导收藏或留言（约10%）"}]','干货、教程、方法','「又熬夜改方案了，老板说还不够惊艳。」——这是上周三的我。改到第五版我才反应过来：问题不在方案，在我没在动手前问清「惊艳」的标准。后来我固定三步：动手前复述一遍需求、列两个方向让老板选、定稿前给一版对照。再没返工过。今天就能做：下次接到任务，先复述一遍再动手。','["痛点要具体到一个场景（「周三改到第五版」比「很多人都有这烦恼」强十倍），方案要能照做、不能停在「要努力」", "最容易翻车的地方：痛点太轻读者没共鸣，方案太空没操作性"]','[]','读者带着「我也是」进来，带着「照着做」离开。痛点要具体到一个场景（「周三改到第五版」比「很多人都有这烦恼」强十倍），方案要能照做、不能停在「要努力」。最容易翻车的地方：痛点太轻读者没共鸣，方案太空没操作性。适合干货、教程、方法类。','自媒体助手',8068);
INSERT INTO "framework" VALUES(70,'listicle','清单体','自媒体创作','开头给承诺，中间 3-7 条并列要点，结尾收束。好读、好收藏。','[{"key": "1", "name": "开头承诺", "desc": "告诉读者读完能得到什么，最好带数字（约10%）"}, {"key": "2", "name": "清单条目", "desc": "3-7 条，每条先给一句结论，再用一个具体例子或细节支撑；条目之间互不重复（约75%）"}, {"key": "3", "name": "收束", "desc": "一句话总结，或给出按什么顺序用这份清单（约15%）"}]','清单、干货、避坑','「5 个让我从加班到点走的习惯」1. 下班前留 10 分钟收拾桌面——明天一早不慌；2. 任务按「重要紧急」分四类——先做重要不紧急的；3. 邮件分两次集中回——别让收件箱牵着走；4. 会议必须有议程——没议程的会不去；5. 周五复盘 15 分钟——下周不重复踩坑。','[]','[]','开头给承诺（带数字最好），中间 3-7 条并列，结尾收束。每条先一句结论，再用一个具体例子或细节支撑；条目之间互不重复。好读、好收藏，但条目多了读者会跳着看，少了显得水。3-5 条最稳。','自媒体助手',8069);
INSERT INTO "framework" VALUES(71,'story_three_act','故事三幕','自媒体创作','处境 → 冲突与转折 → 收获。适合「来时路」、个人经历。','[{"key": "1", "name": "起：处境", "desc": "时间、地点、当时的我是什么状态，用细节而不是形容词（约20%）"}, {"key": "2", "name": "承转：冲突与转折", "desc": "遇到了什么事、怎么挣扎、哪一刻变了；只用作者给的素材，不编经历（约50%）"}, {"key": "3", "name": "合：收获与观点", "desc": "这件事让我明白了什么，和读者有什么关系（约30%）"}]','故事、经历、来时路','三年前我在一家创业公司，每天加班到凌晨（处境）。有天项目上线崩了，我熬了 48 小时修完，老板第一句话是「下次别这么晚」（转折）。我才明白：他不在乎我的努力，在乎的是结果别让他担心。从那以后我不再秀加班，开始秀交付。','["承转：冲突与转折：不编经历（约50%）"]','[]','处境用细节而不是形容词（「凌晨三点的办公室」比「很辛苦」强）；冲突与转折要写挣扎和具体那一刻，不是「然后我就成功了」；收获落到对读者有用的观点。只用作者亲历的素材，不编经历——读者一眼能看出真假。','自媒体助手',8070);
INSERT INTO "framework" VALUES(72,'contrarian','反常识观点','自媒体创作','先抛一个和直觉相反的结论，再用论据说服。容易出爆款，也容易翻车，论据要硬。','[{"key": "1", "name": "反常识结论", "desc": "一句话抛出和大多数人直觉相反的判断（约10%）"}, {"key": "2", "name": "常见误区", "desc": "先把大家通常怎么想说清楚，显得公平（约20%）"}, {"key": "3", "name": "论据", "desc": "用亲历、类比或素材里的数据证明；没有出处的数字不要写（约45%）"}, {"key": "4", "name": "适用边界", "desc": "主动说明这个结论在什么情况下不成立（约15%）"}, {"key": "5", "name": "结论", "desc": "回到开头的判断，给读者一个可带走的看法（约10%）"}]','观点、反常识','「别做时间管理，做精力管理。」大多数人以为效率靠挤时间，其实一天里高效时段就 2-3 小时，剩下的时间硬撑也出不了活。我把每天的深度工作放在上午 10 点前，下午只做沟通和杂事，产出反而高。但如果你是夜型人，这套要反过来。','["容易出爆款也容易翻车——论据不硬就成嘴炮"]','[]','先抛反常识结论，再说大家通常怎么想（显得公平），然后用亲历或素材里的数据论证，最后主动说清「什么时候不成立」。容易出爆款也容易翻车——论据不硬就成嘴炮。主动说清边界反而更可信。','自媒体助手',8071);
INSERT INTO "framework" VALUES(73,'compare','对比测评','自媒体创作','定标准 → 逐项对比 → 给结论和适合人群。','[{"key": "1", "name": "背景与标准", "desc": "为什么要比、按哪几个维度比（约15%）"}, {"key": "2", "name": "逐项对比", "desc": "每个维度写清各自表现，给出判断依据（约50%）"}, {"key": "3", "name": "结论与适合人群", "desc": "不同需求的人分别该选哪个（约25%）"}, {"key": "4", "name": "避坑提醒", "desc": "容易被忽略的一两个坑（约10%）"}]','测评、对比、选购','「三款备菜盒横评」标准：密封性、微波加热、价格。乐扣密封最好但最贵；宜家便宜但汤汁会渗；国产某牌微波可加热但密封一般。常带汤选乐扣，图便宜选宜家，要进微波选国产。避坑：标着「可微波」的不一定耐高温，看材质标识。','["先定标准再逐项对比，最后给「不同需求的人分别选哪个」", "每个维度写清各自表现和判断依据，别只说「A 更好」", "结尾加一条避坑提醒，容易被忽略的坑往往最有用"]','[]','先定标准再逐项对比，最后给「不同需求的人分别选哪个」。每个维度写清各自表现和判断依据，别只说「A 更好」。结尾加一条避坑提醒，容易被忽略的坑往往最有用。','自媒体助手',8072);
INSERT INTO "framework" VALUES(74,'before_after','前后变化','自媒体创作','之前 → 转折点 → 做了什么 → 之后。适合讲习惯、方法带来的改变。','[{"key": "1", "name": "之前的状态", "desc": "具体、可感，最好有一个画面（约20%）"}, {"key": "2", "name": "转折点", "desc": "是什么让我决定改变（约15%）"}, {"key": "3", "name": "做了什么", "desc": "具体动作和坚持的细节（约40%）"}, {"key": "4", "name": "之后的变化", "desc": "变化要具体，不夸大（约15%）"}, {"key": "5", "name": "给读者的建议", "desc": "读者可以从哪一步开始（约10%）"}]','经历、改变、习惯','一年前我 75 公斤，爬三楼喘（之前）。体检报告那天我决定改（转折）。每天早起走 30 分钟，戒掉夜宵，记饮食（做了什么）。现在 68 公斤，爬楼不喘了。建议：别一上来就跑步，先从每天走 30 分钟开始。','[]','[]','之前要有画面（具体到场景），转折点要具体（一句话、一件事），做了什么要写动作不是写决心，之后的变化要可感不夸大。最后给读者一个能从哪一步开始的建议。','自媒体助手',8073);
INSERT INTO "framework" VALUES(75,'qa','答读者问','自媒体创作','引用原问题 → 先给结论 → 展开 → 建议。','[{"key": "1", "name": "读者的问题", "desc": "原样引用读者的问题，保留他的处境（约10%）"}, {"key": "2", "name": "先给结论", "desc": "一两句直接回答（约15%）"}, {"key": "3", "name": "展开分析", "desc": "为什么这么答，分几个层次说（约50%）"}, {"key": "4", "name": "具体建议", "desc": "他明天就能做的事（约20%）"}, {"key": "5", "name": "邀请提问", "desc": "欢迎有类似问题的人留言（约5%）"}]','答疑、问答','读者问：「转行做产品经理，没经验怎么入行？」直接答：先在小项目里把「需求文档 + 数据复盘」跑一遍，比考证有用。展开：招聘方看的是你能不能把一件事从 0 推到 1，不是证书。建议：找公司里一个产品经理，跟他做一个小需求，把过程写成复盘。','["原样引用读者问题，保留他的处境，别改写"]','[]','原样引用读者问题，保留他的处境，别改写。直接答在前一两句，展开在后。展开分几个层次说清「为什么这么答」，具体建议落到「他明天就能做的事」。最后邀请有类似问题的人留言。','自媒体助手',8074);
INSERT INTO "framework" VALUES(76,'pitfalls','避坑指南','自媒体创作','每个坑写清经过、代价和避法。','[{"key": "1", "name": "场景引入", "desc": "什么情况下会踩这些坑（约10%）"}, {"key": "2", "name": "坑与避法", "desc": "3-5 个坑，每个写：怎么踩进去的、付出了什么代价、下次怎么避开（约70%）"}, {"key": "3", "name": "总清单", "desc": "把避法收成一份能对照检查的清单（约20%）"}]','避坑、经验','「我踩过的 3 个外包坑」1. 没签验收标准——尾款拖了三个月，下次合同里写清「交付物 + 验收周期」；2. 只聊价格不聊维护——上线后改一个 bug 报价 2000，下次谈清维护期；3. 没留源码——人跑了项目废了，下次合同写「源码随交付」。','["别只说「要注意」，要说「这样避」——读者要的是动作不是提醒"]','[]','每个坑写清三件事：怎么踩进去的、付出了什么代价、下次怎么避开。3-5 个坑，收成一份能对照检查的清单。别只说「要注意」，要说「这样避」——读者要的是动作不是提醒。','自媒体助手',8075);
INSERT INTO "framework" VALUES(77,'behind_scenes','幕后故事','自媒体创作','成果先行 → 幕后过程 → 意外与取舍。','[{"key": "1", "name": "成果先行", "desc": "先展示做成了什么（约15%）"}, {"key": "2", "name": "幕后过程", "desc": "怎么做出来的，关键节点（约45%）"}, {"key": "3", "name": "意外与取舍", "desc": "遇到的意外、放弃了什么、为什么（约25%）"}, {"key": "4", "name": "感受与邀请", "desc": "真实感受，邀请读者聊聊（约15%）"}]','幕后、经历、故事','「这个号做了 10 万粉」成果先行。前三个月只有 200 粉，我差点放弃（过程）。后来砍掉两个栏目只留一个，是最大的转折（取舍）。意外是：最火的那篇是我以为最没人看的。感受：做内容比想象中孤独，但找到节奏后很踏实。','["取舍部分最值钱——读者想看的是「为什么不要那个」"]','[]','先展示做成了什么（成果先行），再讲怎么做出来的关键节点（幕后过程），然后讲遇到的意外、放弃了什么、为什么（意外与取舍），最后讲真实感受并邀请读者聊。取舍部分最值钱——读者想看的是「为什么不要那个」。','自媒体助手',8076);
INSERT INTO "framework" VALUES(78,'weekly_review','复盘 / 周记','自媒体创作','一句话总结 → 做了什么 → 学到什么 → 下一步。','[{"key": "1", "name": "一句话总结", "desc": "这段时间最重要的一件事（约10%）"}, {"key": "2", "name": "做了什么", "desc": "按重要程度写两三件（约30%）"}, {"key": "3", "name": "学到什么", "desc": "每条对应上面的一件事（约30%）"}, {"key": "4", "name": "下一步", "desc": "接下来打算怎么做（约20%）"}, {"key": "5", "name": "邀请读者", "desc": "请读者分享他的做法（约10%）"}]','复盘、周记、成长','「这周最重要的一件事：把发布流程跑通了。」做了：写了 3 篇、改了发布模板、搭了素材库。学到：模板省的不是时间，是决策；素材库越早搭越好。下一步：下周把口播流程也跑通。你呢？这周最得意的一件事是什么？','["一句话总结这段时间最重要的一件事，做了什么按重要程度写两三件，学到什么每条对应上面的一件事（别空谈感悟），下一步具体到「下周几做什么」，最后邀请读者分享他的做法"]','[]','一句话总结这段时间最重要的一件事，做了什么按重要程度写两三件，学到什么每条对应上面的一件事（别空谈感悟），下一步具体到「下周几做什么」，最后邀请读者分享他的做法。','自媒体助手',8077);
INSERT INTO "framework" VALUES(79,'xhs_seed','小红书种草五段式','自媒体创作','抓眼开头 → 真实场景 → 三个亮点 → 使用细节 → 互动。','[{"key": "1", "name": "抓眼开头", "desc": "直接给结果或痛点，一两句，可以带 emoji（约12%）"}, {"key": "2", "name": "我的真实场景", "desc": "我在什么情况下用、为什么需要（约20%）"}, {"key": "3", "name": "三个亮点", "desc": "每个亮点一小段，写具体体验，不写参数堆砌（约40%）"}, {"key": "4", "name": "使用细节与注意", "desc": "怎么用更好、什么人不适合（约18%）"}, {"key": "5", "name": "总结与互动", "desc": "一句话总结，引导收藏或评论区交流（约10%）"}]','种草、好物、推荐','「这玩意儿救了我一命 😭」
INSERT INTO "framework" VALUES(80,'xhs_tutorial','小红书教程','自媒体创作','结果前置 → 准备 → 分步 → 易错点 → 收藏引导。','[{"key": "1", "name": "结果前置", "desc": "先描述做完是什么效果（约10%）"}, {"key": "2", "name": "准备什么", "desc": "工具、材料或前提条件（约15%）"}, {"key": "3", "name": "分步操作", "desc": "步骤 1、2、3，每步一两句，关键处写数值或时长（约55%）"}, {"key": "4", "name": "易错点", "desc": "最容易做错的一两处（约12%）"}, {"key": "5", "name": "收藏引导", "desc": "提示收藏备用（约8%）"}]','教程、干货','「3 分钟学会用 AI 写大纲」
INSERT INTO "framework" VALUES(81,'dy_hook_3','短视频口播：钩子 + 三点','自媒体创作','3 秒钩子 → 为什么听我说 → 三个要点 → 总结互动。','[{"key": "1", "name": "3 秒钩子", "desc": "一句话抓住人：反问、反常识或结果（约8%）"}, {"key": "2", "name": "为什么听我说", "desc": "一句话亮明身份或经历（约10%）"}, {"key": "3", "name": "要点一", "desc": "一句结论 + 一个例子，口语化（约22%）"}, {"key": "4", "name": "要点二", "desc": "同上，和要点一不重复（约22%）"}, {"key": "5", "name": "要点三", "desc": "同上（约22%）"}, {"key": "6", "name": "总结与互动", "desc": "一句话总结，抛一个问题让观众评论（约16%）"}]','口播、干货','「为什么你越努力越穷？」
INSERT INTO "framework" VALUES(82,'dy_story','短视频口播：反转故事','自媒体创作','悬念开场 → 经过 → 反转 → 观点 → 互动。','[{"key": "1", "name": "悬念开场", "desc": "先说结果或最冲突的一刻（约12%）"}, {"key": "2", "name": "事情经过", "desc": "按时间讲，短句（约38%）"}, {"key": "3", "name": "反转", "desc": "和观众预期不一样的地方（约20%）"}, {"key": "4", "name": "观点", "desc": "这件事说明了什么（约20%）"}, {"key": "5", "name": "互动", "desc": "问观众怎么看（约10%）"}]','口播、故事','「我花 10 万报的班，让我最值钱的不是课。」
INSERT INTO "framework" VALUES(83,'sph_view','视频号口播：观点 + 亲历','自媒体创作','真诚开场 → 我的观点 → 两段亲历 → 给观众的建议 → 转发引导。','[{"key": "1", "name": "真诚开场", "desc": "一个观点或具体场景直接切入，不用夸张标题（约10%）"}, {"key": "2", "name": "我的观点", "desc": "一句话说清你的看法（约12%）"}, {"key": "3", "name": "亲历一", "desc": "自己或身边人的真实经历：时间、地点、数字（约25%）"}, {"key": "4", "name": "亲历二", "desc": "另一个经历，最好和第一个形成对照（约23%）"}, {"key": "5", "name": "给观众的建议", "desc": "明天就能做的一件事（约18%）"}, {"key": "6", "name": "转发引导", "desc": "一句值得转发的总结，请大家转给需要的人（约12%）"}]','口播、经验、观点','「孩子上小学前，我只做了一件事，后来省了很多心。」
INSERT INTO "framework" VALUES(84,'gzh_deep','公众号深度长文','自媒体创作','引子 → 问题 → 三个分论点 → 回到读者 → 结语。','[{"key": "1", "name": "引子", "desc": "一个故事、现象或新闻引出话题（约12%）"}, {"key": "2", "name": "提出问题", "desc": "把要讨论的问题说清楚（约8%）"}, {"key": "3", "name": "分论点一", "desc": "小标题 + 论证（约22%）"}, {"key": "4", "name": "分论点二", "desc": "小标题 + 论证（约22%）"}, {"key": "5", "name": "分论点三", "desc": "小标题 + 论证（约18%）"}, {"key": "6", "name": "回到读者", "desc": "这和读者自己有什么关系、可以怎么做（约12%）"}, {"key": "7", "name": "结语", "desc": "一句有余味的收尾（约6%）"}]','深度、观点、行业','「为什么大公司留不住年轻人」
INSERT INTO "framework" VALUES(85,'gzh_case','公众号案例拆解','自媒体创作','案例速览 → 关键动作 → 背后逻辑 → 可借鉴清单。','[{"key": "1", "name": "案例速览", "desc": "发生了什么，一段说完（约15%）"}, {"key": "2", "name": "关键动作拆解", "desc": "他们做对了哪几件事（约45%）"}, {"key": "3", "name": "背后逻辑", "desc": "为什么这样做有效（约25%）"}, {"key": "4", "name": "可借鉴清单", "desc": "读者能拿走的三五条（约15%）"}]','案例、拆解、行业','「瑞幸怎么从崩盘到反超」
INSERT INTO "framework" VALUES(86,'zhihu_answer','知乎回答','自媒体创作','先给结论 → 亮明身份 → 分点论证 → 反方与边界 → 总结。','[{"key": "1", "name": "先给结论", "desc": "第一段直接回答问题（约10%）"}, {"key": "2", "name": "身份与经历", "desc": "为什么我有资格回答（约10%）"}, {"key": "3", "name": "分点论证", "desc": "分点展开，每点有论据（约55%）"}, {"key": "4", "name": "反方与边界", "desc": "什么情况下结论不成立（约15%）"}, {"key": "5", "name": "总结", "desc": "重申结论（约10%）"}]','问答、观点、干货','「30 岁转行做程序员来得及吗？」
INSERT INTO "framework" VALUES(87,'weibo_short','微博短评','自媒体创作','一句观点 → 一个理由 → 态度收尾。','[{"key": "1", "name": "观点", "desc": "一句话亮明态度（约25%）"}, {"key": "2", "name": "理由", "desc": "一个最有力的事实或理由（约45%）"}, {"key": "3", "name": "收尾", "desc": "态度收尾，可带一个话题标签（约30%）"}]','观点、热点','「别再吹「996 是福报」了。」
INSERT INTO "framework" VALUES(88,'bili_explainer','B 站科普脚本','自媒体创作','开场问题 → 背景 → 核心讲解 → 案例 → 总结与三连。','[{"key": "1", "name": "开场问题", "desc": "一个让人好奇的问题（约10%）"}, {"key": "2", "name": "背景知识", "desc": "理解后面内容需要知道的（约20%）"}, {"key": "3", "name": "核心讲解", "desc": "分段讲清楚，每段一个小标题（约45%）"}, {"key": "4", "name": "案例演示", "desc": "一个具体例子（约15%）"}, {"key": "5", "name": "总结与互动", "desc": "总结要点，引导互动（约10%）"}]','科普、讲解','「为什么 AI 会「幻觉」？」
INSERT INTO "framework" VALUES(89,'golden_circle','黄金圈：为什么 → 怎么做 → 做什么','结构表达','先讲为什么，再讲怎么做，最后讲具体做什么。讲理念、讲选择、讲品牌，比直接给方法更打动人。','[{"key": "1", "name": "为什么 Why", "desc": "先讲原因和信念：这件事为什么值得做、你为什么在乎，具体到一个痛点或一个场景（约30%）"}, {"key": "2", "name": "怎么做 How", "desc": "讲做这件事的原则和方法，和别人不一样的地方在哪（约35%）"}, {"key": "3", "name": "做什么 What", "desc": "落到具体的动作、步骤、产品或内容，读者看完知道下一步做什么（约25%）"}, {"key": "4", "name": "收尾", "desc": "回到「为什么」，用一句话把三层串起来（约10%）"}]','观点、知识、品牌、科普','为什么：我做这个号，是因为见过太多人工作十年还在用第一年的方法干活（为什么）。怎么做：所以每篇我只讲一个能马上用上的方法，并且一定附上我自己试过的结果（怎么做）。做什么：这周讲的是「用三张表管住一个项目」，下面是三张表的模板和填法（做什么）。','["为什么这一段要具体到一个痛点或信念，不能是「因为很重要」这种空话"]','[]','大多数人从「做什么」讲起，黄金圈反过来：先讲为什么（原因、重要性、你相信什么），读者认同了，「怎么做」才听得进，「做什么」才愿意照做。为什么这一段要具体到一个痛点或信念，不能是「因为很重要」这种空话；怎么做讲原则和方法；做什么落到具体动作或产品。适合知识讲解、价值观、个人品牌、产品介绍。','自媒体助手',88);
INSERT INTO "framework" VALUES(90,'ride','RIDE 说服改变','说服与谈判','风险 → 利益 → 差异 → 影响。劝读者改掉一个旧做法、换一种新做法时用。','[{"key": "1", "name": "风险 R", "desc": "继续现在的做法会有什么具体损失，用场景或数据说，不夸大、不制造焦虑（约25%）"}, {"key": "2", "name": "利益 I", "desc": "换成新做法能得到什么，具体可感（约30%）"}, {"key": "3", "name": "差异 D", "desc": "这个做法和别的方法有什么不同，为什么选它（约25%）"}, {"key": "4", "name": "影响 E", "desc": "主动说一条代价或副作用，说明代价有限、怎么应对，最后给一个开始的小动作（约20%）"}]','说服、观点、习惯、避坑','还在用微信收藏夹存资料？三个月后你会发现找不到、也不会再看（风险）。换成每周一次把收藏整理进一个文档，用的时候一搜就有，写东西素材也不愁（利益）。和那些复杂的知识管理软件不同，这个方法只要一个文档、每周 20 分钟（差异）。代价是前两周要逼自己固定时间整理，但养成习惯后几乎不费力（影响）。','["RIDE 的顺序不能乱：先说继续老做法的风险（人对失去比获得更敏感），再说换新做法的利益，然后讲这个做法和别的方法的差别，最后主动说一条它的代价或副作用，并说明代价有限——太完美反而让人起疑", "风险要真实具体，不要吓唬人"]','[]','读者已经有自己的习惯和决定，直接讲新方法的好处往往没用。RIDE 的顺序不能乱：先说继续老做法的风险（人对失去比获得更敏感），再说换新做法的利益，然后讲这个做法和别的方法的差别，最后主动说一条它的代价或副作用，并说明代价有限——太完美反而让人起疑。风险要真实具体，不要吓唬人。','自媒体助手',6089);
INSERT INTO "framework" VALUES(91,'scp_i','行业分析 SCP+I','结构表达','行业结构 → 玩家打法 → 业绩表现 → 新变化与机会。写行业观察、赛道分析用。','[{"key": "1", "name": "行业结构 S", "desc": "这个行业怎么赚钱、产业链和格局是什么样，讲给外行也能听懂（约25%）"}, {"key": "2", "name": "玩家打法 C", "desc": "头部和有特色的玩家各用什么策略，挑两三家对比（约25%）"}, {"key": "3", "name": "业绩表现 P", "desc": "各家打法的结果：规模、增长、口碑；数字要有出处，没有就定性说（约20%）"}, {"key": "4", "name": "新变化 I", "desc": "打破原有平衡的新需求、新政策或新技术（约20%）"}, {"key": "5", "name": "机会与判断", "desc": "这个变化带来什么机会、意味着什么，给出你的判断和适用边界（约10%）"}]','行业、分析、商业','「预制菜还有机会吗？」结构：上游是食品厂，下游靠商超和电商，毛利集中在品牌方。行为：头部品牌靠铺渠道，新品牌靠细分场景（一人食、健身餐）。业绩：头部增速放缓，细分品牌在电商平台增长更快。冲击：学校预制菜争议让消费者更在意配料表——下一个机会在「配料表干净」的细分品牌。','[]','[]','先讲这个行业怎么赚钱、格局怎样（结构），再讲头部和有特色的玩家用什么打法抢份额（行为），然后看各家的结果——营收、用户、口碑（业绩），最后讲打破原有平衡的新变化：新需求、新政策、新技术（冲击），并由它引出机会或判断。数据必须有出处，没有出处的用定性描述，不编数字。','自媒体助手',90);
INSERT INTO "framework" VALUES(92,'elevator','一分钟讲清：电梯演说','结构表达','共识问题 → 核心观点 → 怎么得出 → 数据支持 → 解决办法。一分钟讲清一件事，适合口播开场和短视频。','[{"key": "1", "name": "共识问题", "desc": "一个大家都认可、没争议的问题，让听的人点头（约15%）"}, {"key": "2", "name": "核心观点", "desc": "在这个问题下，你和别人不一样的那个判断（约20%）"}, {"key": "3", "name": "怎么得出", "desc": "一句话说明这个观点是怎么来的：一次经历、一次观察或一个推理（约20%）"}, {"key": "4", "name": "数据支持", "desc": "用数字或具体事实撑住观点；数字只用素材或档案里有的（约20%）"}, {"key": "5", "name": "解决办法", "desc": "顺着观点给出一个具体可做的办法（约25%）"}]','口播、短评、观点','谁都知道开会太多（共识）。但我发现真正浪费时间的不是会多，是没有结论的会（观点）。我统计了自己一个月的 32 个会（怎么得出），其中 19 个散会时没有任何决定（数据）。所以我现在只做一件事：会前发一句话「这次会要定下什么」，定不下来就不开（办法）。','["核心观点：你和别人不一样的那个判断（约20%）"]','[]','先说一个大家都认可、没争议的问题做铺垫，再抛出你在这个问题下的核心观点，一句话讲清这个观点怎么得出来的，然后用数据支持（这一步必须有数，没有数就说具体的事实），最后顺理成章给出办法。整篇要短：每一步一两句话，一分钟能说完。','自媒体助手',91);
INSERT INTO "framework" VALUES(93,'balance','天秤式观点：一方面 / 另一方面 / 平心而论','结构表达','先讲正方，再讲反方，最后给出自己权衡后的判断。写有争议的话题，显得公允、不站队也有态度。','[{"key": "1", "name": "抛出问题", "desc": "把有争议的问题摆出来，说明为什么值得讨论（约10%）"}, {"key": "2", "name": "一方面", "desc": "把一方的理由讲足，用例子或事实支撑，让持这个观点的人也认同（约30%）"}, {"key": "3", "name": "另一方面", "desc": "把另一方的理由同样讲足，不要故意写弱（约30%）"}, {"key": "4", "name": "平心而论", "desc": "给出自己权衡后的明确判断，说清在什么条件下偏向哪边，不和稀泥（约30%）"}]','观点、争议、思辨','「年轻人该不该裸辞？」一方面，裸辞能让你彻底停下来想清楚方向，很多人的转折都发生在空窗期。另一方面，没有收入的焦虑会让人急着随便找个工作，反而重蹈覆辙。平心而论：手里有半年以上生活费、并且已经想好要试什么，可以裸辞；只是「不想干了」，先别辞，边干边找。','["有争议的话题，一上来就站队容易招骂，也显得片面", "不能和稀泥：结尾一定要有明确的倾向和理由"]','[]','有争议的话题，一上来就站队容易招骂，也显得片面。先把一方的道理讲足（一方面），再把另一方的道理讲足（另一方面），两边都要讲到对方阵营的人也认同；最后「平心而论」给出自己的判断和条件——什么情况下更偏向哪边。不能和稀泥：结尾一定要有明确的倾向和理由。','自媒体助手',92);
INSERT INTO "framework" VALUES(94,'timeline','时间轴：过去 → 现在 → 未来','结构表达','过去怎样 → 现在怎样 → 接下来会怎样。讲趋势、讲个人成长、讲一个行业的变化。','[{"key": "1", "name": "主线", "desc": "一句话点出要讲的是什么在变（约10%）"}, {"key": "2", "name": "过去", "desc": "当时的样子、为什么那样，用一个具体场景或事实（约25%）"}, {"key": "3", "name": "现在", "desc": "现在变成了什么样、是什么让它变的（约30%）"}, {"key": "4", "name": "未来", "desc": "接下来会怎样或打算怎么做，说清依据（约25%）"}, {"key": "5", "name": "给读者的提醒", "desc": "这个变化对读者意味着什么、现在可以做什么（约10%）"}]','趋势、成长、行业、规划','「做自媒体的门槛变了」过去：拼的是会不会剪辑、会不会排版，一个人很难做起来。现在：AI 把剪辑、配图的门槛几乎拉平了，拼的变成了有没有真东西可讲。接下来：工具会越来越好用，能沉淀下来的只有你自己的经历和判断——所以现在就该开始记录。','["按时间讲变化，读者最容易跟上", "未来写你的判断或计划，要有依据不能空想", "三段要有一条主线贯穿（比如「门槛」「成本」「人的角色」），不能写成三段不相干的流水账"]','[]','按时间讲变化，读者最容易跟上。过去写当时的样子和为什么那样；现在写变了什么、变化的原因；未来写你的判断或计划，要有依据不能空想。三段要有一条主线贯穿（比如「门槛」「成本」「人的角色」），不能写成三段不相干的流水账。也可以换成短期 / 中期 / 长期，讲计划和规划。','自媒体助手',93);
INSERT INTO "framework" VALUES(95,'micro_course','课程稿：微课八步','即兴与当众','破冰 → 导入 → 主题 → 背景 → 目录 → 展开 → 回顾 → 结尾。上台讲一节微课、做培训分享用。','[{"key": "1", "name": "破冰", "desc": "问候 + 自我介绍 + 今天讲什么；连问三个「想不想」，每问后写（停顿，等回应）（请举手，请放下），最后请大家给自己掌声（约8%）"}, {"key": "2", "name": "导入", "desc": "约 1 分钟、200 字：用亲历场景、新闻、数据或名言引发共鸣，最后点出听众心里的担心或痛点（约10%）"}, {"key": "3", "name": "主题", "desc": "一句话点题：「今天我想和大家谈一谈……」，带上你的核心主张（约3%）"}, {"key": "4", "name": "背景", "desc": "可选，约 200 字：两句话讲讲师的经历、两句话讲成绩，用数据说话；只用作者给的真实经历，不编（约6%）"}, {"key": "5", "name": "目录", "desc": "说清接下来分几个模块，逐个点名：「分别是 1、2、3……」；能起个好记的名字更好，比如首字母拼成一个词（约4%）"}, {"key": "6", "name": "展开", "desc": "只挑一个模块重点讲：先提醒「下面很干货」，再按是什么 → 为什么（可先问台下）→ 怎么做（归纳成好记的几条）→ 举例 → 训练（当场做或留作课后练习）（约56%）"}, {"key": "7", "name": "回顾", "desc": "用提问带全场回顾每个模块（「第一模块是？」写上等回应），夸一句、要一次掌声，送一句和主题相关的金句（约8%）"}, {"key": "8", "name": "结尾", "desc": "号召课后学以致用，问「要不要做到？」，再要一次掌声，送祝福，最后「本次课程到此结束，谢谢大家！」（约5%）"}]','课程、培训、微课、演讲、分享','《AI 的奇思妙用》（节选）
INSERT INTO "framework" VALUES(96,'belief','信念萃取与植入','团队管理','故事引入 → 点出问题行为 → 理解背后信念 → 扩大格局 → 植入新信念 → 提出目标行为。管理者讲话、团队动员、改变别人的一个做法时用。','[{"key": "1", "name": "故事引入", "desc": "一段亲历故事或新闻，有细节、有转折，结论就是要植入的信念；别一开口就讲道理（约40%）"}, {"key": "2", "name": "故事的结论", "desc": "从故事里收出一句话，和后面要植入的信念同一个意思（约7%）"}, {"key": "3", "name": "问题行为", "desc": "「就像我们有些……」点出现在的问题行为：写事实、写过程，不点名、不指责（约8%）"}, {"key": "4", "name": "理解背后信念", "desc": "「我非常理解……」真心认同对方这样做的理由，用「因为……所以」或「只有……才能」说出来（约10%）"}, {"key": "5", "name": "扩大格局", "desc": "「但是……」把视角拉高：放大到公司、行业或更长的时间，说明原来的想法不够用（约12%）"}, {"key": "6", "name": "植入信念", "desc": "「希望大家记住……」一句话，格式「行为 → 价值」，正对着背后信念、突出对对方的价值（约8%）"}, {"key": "7", "name": "目标行为", "desc": "「我要求大家做到……」具体、可执行、符合人性（约8%）"}, {"key": "8", "name": "价值收尾", "desc": "「只有这样，才能……」落到对对方的好处，加一句鼓励（约7%）"}]','说服、管理、演讲、动员、培训','【萃取】问题行为：疫情居家期间，讲师不参加线上培训、作息混乱。背后信念：该放松时放松，才有精力在该努力时努力。目标行为：按要求参加线上培训，做好个人学习规划。植入信念：人和人之间的差距，是在无人约束时拉开的。
